        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || next_unusable || stranded {
            score -= 20.0 + 15.0 * (1.0 - fit_ratio);
