            score += 300.0 + 300.0 * (1.0 - progress);
        }
    }

    // Consolidate: prefer bins whose residual deviates below mean,
    // and favor placements that leave post_residual near mean.
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    score += (post_residual as f64 - mean_residual) * 0.4;

    score
}

