                && mean_residual >= next_item_size as f64
            {
                score += 20.0;
            }
        }
    }

    // Dead-zone accounting: residue in the dead zone scaled by depth and sink.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if post_residual as f64 > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Sub-mean slack penalty: slack below mean residual is likely to strand.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Dead-zone depth refinement: residue reachable by the next item is much
    // less dead than residue below it; scale the gap quadratically.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Residual-value conservation: mid-size usable residue is valuable while
    // the stream is long.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity: keep pairable leftovers in the fleet.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (1..=10) are wasted capacity. Penalize them hard.
    let dead_threshold: u32 = 10;
    if post_residual > 0 && post_residual <= dead_threshold {
        score += 500.0 + (dead_threshold - post_residual) as f64 * 20.0;
    }

    // Semi-dead space: gaps that can only fit tiny items are also risky.
    if post_residual > dead_threshold && post_residual <= 25 {
        score += (25 - post_residual) as f64 * 4.0;
    }

    // Reward bins whose residual matches the next item (lookahead synergy).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 300.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        score -= 30.0; // bin stays usable for the lookahead item
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Open-bin pressure: with many open bins, prefer packing into existing ones
    // rather than fragmenting; with few bins, tolerate spreading.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score -= pressure * 25.0;

    // Slightly prefer bins tighter than the mean residual (compactness).
    score += (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate: only attractive when existing bins would create dead space
    // or the item nearly empties a fresh bin's usefulness.
    if bin_residual == bin_capacity {
        score += 60.0; // default mild penalty for opening a new bin
        if post_residual >= 90 {
            score -= 200.0; // huge item: fresh bin is fine
        }
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative anyway
        }
        // If any open bin would leave dead space, opening fresh is better.
        // Approximate via mean residual: crowded bins suggest poor fits.
        if mean_residual < item_size as f64 * 1.2 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
