    }

    // Early-stream consolidation: keep residuals above mean early.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
