        score += 80.0; // unusable sliver
    }

    // Harmonic coupling: does post_residual match the next item size (perfect chain)?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 400.0; // chain fit: next item exactly fills this bin
        } else if pr > next_item_size {
            score -= 50.0 * (pr / next_item_size.max(1)) as f64; // next item still fits here
        } else {
            score += (next_item_size - pr) as f64 * 1.5; // next item won't fit: fragmentation risk
        }
    }

    // Modulo arithmetic on residual: residuals that are multiples of common item sizes
    // (10, 20, 25, 50) are reusable "harmonic" capacities.
    let harmonics: [u32; 4] = [10, 20, 25, 50];
    for h in harmonics.iter() {
        if pr >= *h && pr % h == 0 {
            score -= 40.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Many open bins: penalize spreading, favor consolidation.
    if open_bins_count > 3 {
        score += (open_bins_count as f64) * 2.0;
    }

    // New-bin candidate: only attractive when current bin would leave large,
    // awkward residuals relative to mean residual.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 120.0;
        // attractive if existing bins fit poorly (post_residual very small but nonzero)
        if pr > 0 && pr < 15 && next_item_size > 0 && next_item_size > pr {
            score -= 100.0;
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 60.0;
    }

    // Mild preference for bins below mean residual (fill emptier bins first
    // keeps tight bins available for small items).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 * (1.0 + (10 - post_residual) as f64);
    }

    // Reward tight fits (small post_residual in the usable range).
    if post_residual <= 20 && post_residual > 10 {
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when bins already exist.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0; // first item must open a bin
    }

    // New-bin candidate: penalize unless current bin would leave big dead space.
    if bin_residual == bin_capacity {
        let dead_space_risk = if post_residual > 0 && post_residual <= 10 { 0.0 } else { 25.0 };
        score += dead_space_risk + 5.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Prefer bins whose residual deviates below mean (consolidate large gaps).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.3;
    }

    // Penalize dead space that cannot host the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 2.0;
    }

    // Compare post_residual against mean residual of open bins:
    // leaving below-average waste is good, above-average waste is bad.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.5;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless the item
    // is huge relative to residual capacity of existing bins or stream is early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * bin_capacity as f64;
        if fitting_bins_count > 0 && !big_item {
            score += 300.0 + 400.0 * (1.0 - progress);
        } else {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post-residual.
    let tight = (post_residual as f64) / (bin_capacity as f64);
    score -= (1.0 - tight) * (1.0 - tight) * 18.0;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Dead-space penalty: post-residual too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits exactly into post-residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            // post-residual unusable by next item: penalize proportionally
            score += (next_item_size as f64 - post_residual as f64) * 0.35;
        } else {
            // next item fits, reward leftover shrinkage
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or fit would be very loose.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let looseness = 1.0 - (item_size as f64 / bin_capacity as f64);
        score = 40.0 + looseness * 30.0 - crowding * 5.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // new bin leaves room for the lookahead item
        }
    }

    // Time horizon: early in stream, be conservative (keep bins flexible);
    // late in stream, prioritize closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.10;
    score -= progress * 8.0;

    // Penalize bins far from mean residual (fragmentation signal).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Mild preference for already-open bins vs opening many bins.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * p2 + 3.0 * p3);
    score += 30.0 * coupling;

    // Penalize large residuals late in the stream more aggressively (smooth quartic ramp)
    score += 20.0 * norm_pr * norm_pr * (0.5 + p3);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit_next = if pr >= nxt { 1.0 } else { 0.0 };
        let gap = (pr - nxt).abs() / cap;
        score -= 15.0 * fit_next * (1.0 - gap * gap);
        score += 10.0 * gap * gap;
    }

    // Last-chance bin: strongly favor using it (smooth exponential-like reward)
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + p2);
    }

    // Slight preference for bins tighter than the mean residual (smooth relative term)
    let rel = if mean_residual > 0.0 { (pr - mean_residual) / cap } else { 0.0 };
    score += 8.0 * rel * (1.0 - 0.5 * progress);

    // Prefer consolidating into fewer bins when many are open
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    // New-bin candidate: penalize mildly, more when open bins can absorb the item
    if bin_residual == bin_capacity {
        score += 18.0 * (1.0 - 0.4 * progress) + 5.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes
    // modulo 10 (fine grain) and coarse capacity-fraction buckets.
    let fine_class = post_residual % 10;
    let coarse = (post_residual * 4) / bin_capacity; // 0..=3 coarse fraction buckets

    // Dead-space penalty: leftovers that no typical item (1..=100) can use well.
    // Post-residuals of 0 are perfect; tiny leftovers (1..=9) are near-dead space.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if fine_class <= 2 {
        score += 25.0; // very small unusable sliver
    } else if fine_class >= 8 {
        score += 8.0;  // almost aligned to next decade
    } else {
        score -= 5.0;  // mid-range leftover, moderately reusable
    }

    // Coarse fraction coupling: leaving a quarter/half of the bin is valuable.
    match coarse {
        0 => score += 12.0,          // nearly empty leftover bin -> wasteful use of a fresh bin
        1 => score -= 10.0,          // ~quarter residual: good slot for medium items
        2 => score -= 14.0,          // ~half residual: prime reusable space
        _ => score -= 6.0,           // large residual
    }

    // Lookahead: does the next item fit exactly into the post-residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0; // chain a perfect follow-up
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            let slack_class = slack % 10;
            score -= 18.0 - (slack_class as f64) * 1.2; // tighter lookahead fits rewarded
        } else {
            // next item cannot use this residual: mild penalty scaled by miss size
            let miss = next_item_size - post_residual;
            score += (miss as f64).min(40.0) * 0.35;
        }
    }

    // Integer-division threshold: penalize residuals in (0,10) strictly — classic dead zone.
    if post_residual > 0 && post_residual / 10 == 0 {
        score += 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when the item
    // is large relative to capacity or open bins are all crowded.
    if bin_residual == bin_capacity {
        let crowd = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // reward new bin when item is big and existing residuals are small
        score -= (item_size as f64 / bin_capacity as f64) * 35.0;
        score += crowd * 55.0;           // crowded bins -> new bin looks better
        score -= progress * 8.0;         // late in stream, consolidate slightly less eagerly
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;               // large follow-up benefits from fresh space
        }
    }

    // Mild tie-break: prefer filling bins with below-mean residual (balance preservation).
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Small nudge toward keeping the count of open bins low.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    // A residual gap is "dead" if it cannot fit even the smallest plausible item (1..10).
    // Penalize gaps in [1, 12) very strongly since they are almost always wasted.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    } else if post_residual < 25 {
        // Semi-dead zone: only small items can fit; add moderate penalty.
        score += 18.0;
    }

    // Reward near-perfect fits (tight packing).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // If the next item fits exactly in the post-residual, strongly favor this bin
    // (lookahead chaining creates zero-waste sequences).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual - next_item_size < 8 {
        score -= 25.0;
    }
    // If next item cannot fit in the leftover, the gap is more likely to become dead space.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones
    // over leaving many partially-filled bins around.
    let pressure = open_bins_count as f64 * 2.5;
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean
    // (i.e., it is already quite full), finishing it off is good.
    let this_residual = bin_residual as f64;
    if this_residual < mean_residual - 10.0 {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when the
    // item is large and no open bin offers a decent fit. Penalize the empty-bin
    // call mildly so tight fits in open bins win, but keep it viable for bad fits.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 35.0;
        // But if the current item is large relative to capacity, a fresh bin
        // gives maximal future flexibility.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 45.0;
        }
        // If many bins fit the item, no reason to open a new one.
        if fitting_bins_count > 2 {
            score += 20.0;
        }
    }

    // Early in the stream, slightly favor opening bins to build flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity && progress < 0.2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus when the item fills the bin exactly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // 2-step lookahead: reward when the next item fits exactly in the post residual.
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 500.0;
            } else if next_item_size < post_residual {
                // Next item fits: penalize leftover after the lookahead placement.
                let post2 = post_residual - next_item_size;
                score += post2 as f64 * 0.5;
            } else {
                // Next item does NOT fit here: penalize leaving a gap smaller than next item.
                score += 30.0 + (post_residual as f64) * 0.3;
            }
        }

        // Reward residual small relative to mean residual (tight packing).
        score -= (mean_residual - post_residual as f64) * 0.4;

        // Penalize creating dead space that is hard to fill (small gaps).
        if post_residual > 0 && post_residual < 10 {
            score += 40.0;
        }

        // Last-chance bin: strong reward to use it rather than open a new bin.
        if fitting_bins_count == 1 {
            score -= 200.0;
        }

        // Slight preference for using existing bins over opening new ones as stream progresses.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 20.0;
    }

    // New-bin candidate: neutral baseline with mild penalty, so it only wins when
    // all open bins score poorly (large residuals / bad lookahead matches).
    if bin_residual == bin_capacity {
        score = 250.0 + post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.15 * next_item_size as f64;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here anyway; slight penalty for wasting large residual.
        score += 4.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    // or the item is large and fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = mean_residual / bin_capacity as f64;
        // Penalize opening new bins early or when open bins are mostly empty.
        score += 25.0 + 30.0 * (1.0 - progress);
        // Reward opening a new bin when existing residuals are small (fragmented).
        score -= 20.0 * (1.0 - fragmentation.min(1.0));
        // If item barely fits in any open bin (large item), new bin is decent.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 15.0;
        }
    }

    // Penalize bins whose residual deviates wildly from the mean (keeps pool coherent).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Mild reward for using bins with larger residuals when many bins are open.
    score -= 0.1 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Prefer filling bins more completely as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // Dead-space guard: residuals of 1..9 are nearly useless.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr) - 12.0 * norm_pr * (1.0 - norm_pr);

    // Stream-progress coupling: penalize small residuals more as stream advances
    let tightness = 1.0 - norm_pr;
    score += 20.0 * progress * tightness * tightness * norm_pr;

    // Lookahead: reward if next item fits in post residual (smooth interaction)
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as f64;
        let ratio = (next_item_size as f64 / cap).min(1.0);
        score -= 15.0 * fits * (1.0 - ratio) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Mean residual coupling: prefer bins near the mean (smooth quadratic)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Mild penalty for many open bins to discourage hoarding empties
    score += 0.15 * open_bins_count as f64 * (1.0 - tightness);

    // New-bin candidate: make empty bin attractive only for large items / late stream
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * (1.0 - item_size as f64 / cap) - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // integer-division buckets. Residuals in the "dead zone" (1..10) are
    // almost unusable for items >= 10 traditionally, but sizes 1..100 are
    // possible, so weight small residuals by their divisibility class.
    let pr = post_residual as i64;
    let dead_zone = if pr > 0 && pr < 10 { 1.0 } else { 0.0 };

    // Modulo-10 harmonic class: residuals divisible by 10 align with the
    // coarse grid of typical item sizes and are easier to fill later.
    let mod10 = post_residual % 10;
    let mod10_bonus = match mod10 {
        0 => -6.0,
        5 => -2.0,
        1 | 9 => 2.0,
        _ => 0.0,
    };
    score += mod10_bonus;

    // Penalize dead-zone residuals strongly (wasted space), scaled by
    // how small the residual is relative to capacity.
    score += dead_zone * 25.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a perfect harmonic pair — big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how well it fills.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
            // Extra harmonic alignment: post_residual - next divisible by 5/10.
            let rem = post_residual - next_item_size;
            if rem % 10 == 0 { score -= 6.0; }
            else if rem % 5 == 0 { score -= 3.0; }
        } else {
            // Next item won't fit here: mild penalty scaled by overshoot class.
            let over = (next_item_size - post_residual) as f64;
            score += 4.0 * (over / 10.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Prefer tight fits generally: reward small post_residual via
    // integer-division thresholds.
    let bucket = post_residual / 10; // 0..=10 harmonic bucket
    score -= (10 - bucket.min(10)) as f64 * 1.5;

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well (post_residual small).
    if bin_residual == bin_capacity {
        // Neutral baseline for a fresh bin, adjusted by stream progress:
        // early in the stream, opening bins is cheap; late, prefer filling.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 40.0 * progress - 8.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity / 2 {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    // Mild pressure to consolidate: bins below mean residual are emptier;
    // filling emptier bins first balances residuals.
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals too small for any item (min size 1, but
    // practically unusable if < ~10) are heavy penalties.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64 * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize opening new bins when open bins exist (pressure from open_bins_count).
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 15.0 + 2.0 * open_bins_count as f64;
    }

    // Last-chance bin: strongly favor using it to avoid wasting its space.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 18.0;
    }
    // Penalize if next item cannot fit in post_residual but this bin could hold more.
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Early stream: be slightly greedy with new bins to build good residual structure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins with residual close to item_size (best-fit coupling).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.3;

    // Mean residual coupling: prefer bins deviating favorably from mean.
    score += (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual equals next item's size -> heavy reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 0.5 * item_size as f64;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Next item still fits here: mild reward proportional to closeness.
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(40.0) * 0.4;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize creating dead space.
        let dead = (next_item_size - post_residual) as f64;
        score += dead.min(50.0) * 0.8;
    }

    // Tight fit reward: small post_residual is good, especially near-mean residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize bins whose residual deviates strongly below mean (fragmented bins).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive if nothing fits well (post_residual huge
    // already penalizes it via base term; add mild penalty to prefer reuse).
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large dead space that nothing typical could use later.
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // small unusable sliver is fine (bin nearly perfect)
    } else if post_residual >= 10 {
        // dead space scaled by how much of the capacity it wastes
        score += 0.05 * post_residual as f64;
    }

    // Lookahead: if the next item fits exactly into the post-residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 6.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for leaving awkward gap
            score += 2.0;
        }
    } else {
        // last item: prefer closing bins as tightly as possible
        score -= 10.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // or mean residual suggests open bins are nearly full.
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        // penalize new bins when open bins still have room on average
        score += 30.0 * (1.0 - crowding);
        // late in the stream, prefer consolidating into open bins
        score += 10.0 * progress;
        // many open bins already? discourage proliferation
        score += 1.5 * open_bins_count as f64;
        // if item is large relative to capacity, a fresh bin is reasonable
        score -= 0.15 * item_size as f64;
    }

    // Global state coupling: when mean residual is low, treasure remaining space.
    let scarcity = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score *= 1.0 + 0.5 * scarcity;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);

    // Normalized post-residual and its smooth polynomial couplings.
    let r = post / cap; // in [0,1]
    let r2 = r * r;
    let r3 = r2 * r;

    // Base: prefer small post-residual (tight fits), non-linearly.
    let mut score = 2.0 * r - 1.5 * r2 + 0.8 * r3;

    // Smooth interaction with stream progress: later in the stream,
    // waste is more costly, so tighten the fit preference.
    score *= 1.0 + 0.6 * progress * (1.0 - r2);

    // Reward filling a bin nearly completely (small r) with a smooth bump.
    score -= 0.9 * (1.0 - r3) * (1.0 - progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 1.2 + 0.5 * progress;
    } else {
        // Mild penalty when many bins compete, to break ties toward tighter fits.
        score += 0.05 * (fitting_bins_count.min(10) as f64);
    }

    // Penalize opening a new bin (bin_residual == bin_capacity) unless the item
    // is large relative to capacity; smooth quadratic in item size.
    if bin_residual == bin_capacity {
        let s = item_size as f64 / cap;
        score += 0.8 - 1.0 * s * s - 0.4 * progress;
    }

    // Coupling with mean residual: if open bins are already loose on average,
    // slightly discourage adding more loose space; if this bin is tighter than
    // the mean, reward it.
    let dev = (mean_residual - post) / cap;
    score += 0.15 * dev * (1.0 + progress);

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 0.4 * (1.0 - post / cap) + 0.2 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10 classes of 10 units.
    let post_class = post_residual / 10;
    // Dead-space classes: small residuals are only useful for tiny future items.
    match post_class {
        0 => score -= 25.0,                 // near-perfect fit, excellent
        1 => score -= 15.0,                 // great fit
        2 => score -= 8.0,                  // good fit
        3 | 4 => score -= 3.0,              // decent fit
        5 | 6 => {}                         // neutral
        7 | 8 => score += 6.0,              // awkward gap
        _ => score += 12.0,                 // large gap, wasteful
    }

    // Compatibility: can the lookahead item fit into the post-residual class?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (next_item_size as u32) <= post_residual {
            // Next item fits here: reward proportionally to how well it fills the gap.
            let fill = nxt / (post_residual as f64 + 1.0);
            score -= 10.0 + 15.0 * fill;
        } else {
            // Next item cannot use this residual: penalize proportionally to gap size.
            let gap = (post_residual as f64) / cap;
            score += 4.0 + 10.0 * gap;
            // Extra penalty if next item is large (it will need a fresh bin anyway).
            if next_item_size > 50 {
                score += 3.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only open a new bin when open bins are crowded
    // or the residual would be badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowd = open_bins_count as f64;
        // Base cost of a new bin.
        let mut new_bin_score = cap * 0.6;
        // Cheaper to open new bins early in the stream (more future to amortize).
        new_bin_score -= 20.0 * (1.0 - progress);
        // If many bins are open and mean residual is small, opening a bin is fine.
        if crowd > 3.0 && mean_residual < 20.0 {
            new_bin_score -= 15.0;
        }
        // If the item would leave a large dead space in every existing bin,
        // prefer the new bin.
        if post_class >= 7 {
            new_bin_score -= 10.0;
        }
        score = new_bin_score;
    } else {
        // Slight preference for tighter existing bins beyond raw post_residual.
        let tightness = 1.0 - (bin_residual as f64) / cap;
        score -= 5.0 * tightness;
    }

    // Modulo-based micro-adjustment: residuals that are multiples of common
    // item sizes (10, 20, 25) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 2.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        // Small unusable-ish gap: scale penalty by how close it is to useless.
        score += (20 - post_residual) as f64 * 3.0;
    }

    // Reward exact/tight fits (post_residual small but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // strongly favor this bin (perfect 2-item chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        score -= 5.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 25.0;
    }

    // Open-bin pressure: prefer using bins that already exist; discourage
    // scattering across many bins when mean residual is large.
    score += open_bins_count as f64 * 0.8;

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would create severe dead space.
    if bin_residual == bin_capacity {
        // Base cost of a new bin.
        score += 30.0;
        // But if mean residual across open bins is small (poor fits ahead),
        // a fresh bin is relatively more attractive.
        score -= (mean_residual / bin_capacity as f64) * 20.0;
        // Early in the stream, opening bins is cheaper (more future items to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mild preference for bins with residual close to mean (balanced usage).
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.9 {
        score -= 30.0 * fit_ratio;
    }
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 40.0 - 0.5 * next_fit.min(40.0) as f64;
        if next_item_size == post_residual {
            score -= 45.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual that next item cannot use.
        score += 10.0;
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last chance bin before opening a new one: strong reward to use it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent fits exist; allow it for large items / bad fits.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = fit_ratio < 0.5;
        if poor_fit || open_bins_count == 0 {
            score -= 15.0 + 10.0 * (1.0 - fit_ratio);
        } else {
            score += 25.0 + 20.0 * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for leaving dead space that no plausibly arriving item can use.
    let dead_threshold = 10.0f64.min(bin_capacity as f64 * 0.1);
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 40.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits in the post-residual, this is a great chain.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving medium-size gaps.
            score += 6.0;
        }
    }

    // Tightness coupling: prefer bins whose residual is close to item size.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Global state: with many open bins, prefer filling existing ones (avoid fragmentation).
    let open_pressure = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual < bin_capacity {
        score -= 8.0 * open_pressure;
    }

    // Mean residual coupling: placing into a bin far below mean residual reduces fragmentation.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score += 0.3 * dev;
    }

    // New-bin candidate logic: only attractive early in the stream or when this bin
    // would leave a very awkward gap and other options are scarce.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let awkward = if post_residual > 0 && (post_residual as f64) < 20.0 { 1.0 } else { 0.0 };
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let new_bin_bonus = 25.0 * (1.0 - progress) + 35.0 * awkward + 30.0 * scarcity;
        score -= new_bin_bonus;
        // Discourage opening new bins when plenty of open bins exist.
        score += 4.0 * open_bins_count as f64;
    }

    // Mild time-horizon shaping: later in the stream, prioritize consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with a non-linear (quadratic) coupling
    // that increasingly penalizes large dead space as the stream progresses.
    let mut score = post + (post / cap) * (post / cap) * (1.0 + 2.0 * progress) * cap * 0.5;

    // Smooth cubic penalty on wasted fraction, amplified late in the stream.
    let waste_frac = post / cap;
    score += 20.0 * waste_frac * waste_frac * waste_frac * (0.5 + progress);

    // Tight fits deserve a bonus (subtract), scaled by how full the bin becomes.
    let fill_frac = 1.0 - waste_frac;
    score -= 15.0 * fill_frac * fill_frac;

    // Lookahead coupling: reward bins whose post-residual can host the next item
    // smoothly (smooth via Gaussian-like kernel on the gap).
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let kernel = (-(gap * gap) / (2.0 * 15.0 * 15.0)).exp();
        score -= 10.0 * kernel;
        // Penalize post-residuals that are just barely too small for the next item
        // (dead space that blocks a natural follow-up placement).
        if post < next_item_size as f64 {
            score += 5.0 * (1.0 - post / next_item_size.max(1) as f64).max(0.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (smooth decay with fitting_bins_count).
    if fitting_bins_count >= 1 {
        let last_chance = 1.0 / fitting_bins_count as f64;
        score -= 8.0 * last_chance;
    }

    // New-bin candidate: make opening a new bin mildly attractive early and for
    // large items, but penalize it when existing bins can absorb the item well.
    if bin_residual == bin_capacity {
        let openness = 1.0 - progress;
        let item_frac = item_size as f64 / cap;
        score = cap * 0.6 - 20.0 * openness * (1.0 - item_frac);
        if fitting_bins_count > 0 {
            score += 10.0 * (mean_residual / cap).min(1.0);
        }
    }

    // Mild diversity pressure: many open bins with high mean residual suggests
    // fragmentation; slightly discourage adding to scattered state.
    score += 0.02 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead-space quality via modulo classes
    let pr = post_residual;
    // Class 0: post_residual divisible by 10 -> "clean" slot, likely reusable
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    // Class 1: post_residual in [1..9] -> tiny unusable dead space, penalize
    if pr > 0 && pr < 10 {
        score += 15.0;
    }
    // Perfect fit bonus
    if pr == 0 {
        score -= 50.0;
    }

    // Integer division thresholds: post_residual bucket by quarter capacity
    let quarter = bin_capacity / 4;
    if pr >= 3 * quarter {
        score -= 5.0; // still roomy bin, good
    } else if pr >= quarter {
        score += 3.0; // mid-range leftover, mediocre
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size == pr {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward proportionally, harmonic fraction of capacity
        let frac = next_item_size as f64 / bin_capacity as f64;
        score -= 10.0 * frac;
    } else if next_item_size > pr && pr > 0 {
        // next item won't fit here: leftover becomes dead space
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placements are terrible
    if bin_residual == bin_capacity {
        score += 25.0;
        // early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
