            // If the best existing fit would strand a large orphan, a fresh
            // bin is relatively cheaper.
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            // NEW: if the current item would leave a sliver that cannot host
            // the next item anywhere, opening fresh is cheaper than stranding.
            if next_item_size > 0 && post_residual < next_item_size && post_residual < 0.05 * bin_capacity as f64 {
