    // regardless of fit, weighted by how much of the stream remains so that
    // small leftover space is treated as recoverable value early on.
    if bin_residual != bin_capacity && post_residual > 0 {
        let remaining = (total_items - step_index).max(1) as f64;
        let stream_frac = (remaining / total_items.max(1) as f64).min(1.0);
        let pr = post_residual as f64;
        if pr <= 0.18 * bin_capacity as f64 {
            score -= 10.0 * stream_frac * (1.0 - pr / (0.18 * bin_capacity as f64));
