    // placements that leave residuals in the awkward 20–40% band, steering
    // toward either tight fits or roomy leftovers.
    if fitting_bins_count >= 2 {
        let wr = post_residual as f64 / bin_capacity as f64;
        if wr > 0.2 && wr < 0.4 {
            score += 6.0 * (0.3 - (wr - 0.3).abs()) * 20.0;
        }
    }

    score
}

