    if next_item_size > 0 && post_residual >= 2 * next_item_size && fitting_bins_count >= 2 {
        score -= 9.0;
    }

    // NEW: balance pressure — when many bins are open, mildly prefer the
    // fullest-fitting bin to concentrate residue and free bins earlier.
    if open_bins_count > 6 {
        score += (post_residual as f64 / cap) * 10.0;
    }

    score
}

