    // bins are open, slightly prefer the bin whose post_residual is closest to
    // half of next_item_size*2 (even-split potential), reducing fragmentation.
    if remaining_frac > 0.5 && open_bins_count > 4 && next_item_size > 0 && post_residual >= next_item_size {
        let split_gap = ((post_residual - 2 * next_item_size) as i64).unsigned_abs() as f64;
        score += split_gap * 0.08;
    }

    score
}

