            }
            // NEW: when mean residual is comfortably above the next item's
            // size, opening a fresh bin is cheap — the existing pool can
            // absorb follow-ups. Soften the barrier so we don't hoard bins.
            if next_item_size > 0 && mean_residual > (next_item_size as f64 + 8.0).min(0.3 * cap) {
