            if mean_residual >= item_size as f64 + 2.0 && fit_ratio < 0.65 {
                score += 30.0;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            score += 10.0 * depth * (0.5 + remaining_frac);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer bins leaving the most usable
    // remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement — scale penalty by distance from any
    // plausible future item boundary.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation: reward tight hosts in the chain window.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation: preserve large usable residue mid-stream.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity: smooth gradient toward closing a bin.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // NEW: adaptive dead-zone threshold — bins whose residue sits in the
    // "no typical item fits" band relative to the mean residual are prime
    // consolidation targets; reward filling them tightly.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count > 0 {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.5 && pr > 0.02 * cap {
            score += 8.0 * (1.0 - pr / (mean_residual.max(1.0) * 0.5));
        }
    }

    // NEW: fit-quality vs. residue trade-off — among bins that can host the
    // next item, prefer the one whose post_residual lands closest to the
    // next item size, with a sharper weight when few bins remain usable.
    if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count <= 2 {
        let slack = (post_residual - next_item_size) as f64;
        score -= slack.max(0.0) * 0.0 + slack * 0.18 * (1.0 - remaining_frac);
    }

    // NEW: anti-hoarding — late in the stream, large leftover residue is
    // unlikely to be used; gently penalize keeping spacious bins open.
    if remaining_frac < 0.3 && bin_residual != bin_capacity && post_residual > 0.5 * cap {
        score += 10.0 * (1.0 - remaining_frac) * (post_residual as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened around the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.35;
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
    }

    // Two-step lookahead: discourage tiny unusable slivers.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
    }

    // Compare post_residual against mean residual of open bins.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping: reward near-full bins, penalize half-empty ones.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && post_residual < next_item_size) {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let can_host_next_elsewhere = mean_residual >= next_item_size as f64;
                if !can_host_next_elsewhere {
                    score += 55.0;
                }
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            // NEW: a fresh bin is cheaper when the current best open-bin fit
            // would strand a large orphan; scale the new-bin premium down.
            if next_item_size > 0 && post_residual < next_item_size {
                let orphan_frac = (next_item_size - post_residual) as f64 / cap;
                score -= 90.0 * orphan_frac.min(0.5);
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            score += 10.0 * depth * (0.5 + remaining_frac);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer bins leaving the most usable
    // remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge — when several bins can host the
    // item, prefer the one whose post_residual best matches the next item
    // when the mean residual is low (bins are already tight).
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap — post_residual equal to twice the next
    // item means two consecutive placements can close the bin perfectly.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement — scale the penalty by how far the residue
    // is from ANY plausible future item boundary.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation — bins with residue in the
    // [next, next*3] window are prime hosts for a chain of small fills.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation — preserve large usable residue so late
    // medium items still have homes (reduces forced new bins).
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity — smooth gradient for bins one small item away
    // from closing.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // NEW: best-alternative contrast — when multiple bins fit, compare this
    // bin's post_residual against the mean of fitting bins' residuals and
    // reward being the tightest host, sharpening selection among equals.
    if fitting_bins_count >= 2 && next_item_size > 0 && bin_residual != bin_capacity {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < mean_residual {
            score -= 8.0 * (1.0 - pr / mean_residual.max(1.0));
        } else if pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score += 8.0;
        }
    }

    // NEW: two-item chain feasibility — reward bins that can absorb the next
    // item AND leave room for a second item of similar size, which enables
    // double-fill closures instead of stranding residue.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        let extra = post_residual - 2 * next_item_size;
        if extra <= next_item_size / 4 {
            score -= 14.0;
        }
    }

    // NEW: orphan-risk smoothing — when the item cannot be followed by the
    // next item anywhere (all residuals too small), soften the penalty for
    // bins that at least minimize the stranded amount, steering toward the
    // least-waste placement rather than a flat penalty.
    if next_item_size > 0 && post_residual < next_item_size && fitting_bins_count >= 2 {
        let least_orphan = (next_item_size - post_residual) as f64;
        score -= 6.0 * (1.0 - least_orphan / next_item_size as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
