                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            // MUTATION: opening a fresh bin is also attractive when the
            // best available fit here is mediocre AND the fleet mean
            // residual is already tight — a fresh bin gives future items
            // room to land instead of forcing more strandings.
            if fit_ratio < 0.68 && mean_residual < 0.25 * cap && open_bins_count >= 3 {
                score -= 30.0 * (0.68 - fit_ratio) / 0.68;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
