    // next item needs by only a hair, the bin is effectively closed with
    // minimal waste; reward bins whose post_residual lands in the tight
    // [next, next+6] band more aggressively mid-stream.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual <= next_item_size + 6 {
        score -= 14.0 * remaining_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
