            // would strand the host bin in a wide dead zone while a roomy
            // bin could absorb it with usable slack left over.
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            // NEW: refuse a fresh bin when the best-fitting open bin would
            // still be a perfect host for the next item afterwards.
            if next_item_size > 0 && mean_residual >= next_item_size as f64 + 6.0 {
                score += 30.0;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
