    // Split-fit insurance.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // NEW: dead-zone band compression — residue just below the item size that
    // could have fit is the worst kind of waste; penalize the narrow band
    // [item_size - 8, item_size) quadratically, scaled by remaining stream.
    if bin_residual != bin_capacity
        && post_residual > 0
        && post_residual < item_size
        && item_size >= 9
        && item_size.saturating_sub(post_residual) <= 8
    {
        let depth = (item_size - post_residual) as f64 / 8.0;
        score += 16.0 * (1.0 - depth) * (1.0 - depth) * (0.5 + remaining_frac);
    }

    // NEW: usable-window matching — when the mean residual across open bins
    // is itself a usable host for the next item, prefer candidates whose
    // post_residual stays in that window instead of draining a single bin.
    if next_item_size > 0
        && open_bins_count >= 2
        && mean_residual >= next_item_size as f64
        && post_residual >= next_item_size
    {
        let window = (mean_residual - next_item_size as f64).abs();
        if (post_residual as f64 - mean_residual).abs() <= window.max(3.0) {
            score -= 7.0 * (0.4 + remaining_frac);
        }
    }

    // NEW: perfect-fit gravity for large items — placing a big item into a
    // bin whose residual is barely larger eliminates a bin that no smaller
    // item could use as well; reward tight large-item fits progressively.
    if item_size as f64 > 0.55 * cap && fit_ratio > 0.7 {
        score -= 20.0 * (fit_ratio - 0.7) / 0.3;
    }

    score
}

