    // Reward near-perfect fits strongly, sharpened around the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.35;
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
    }

    // Two-step lookahead: discourage tiny unusable slivers.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
    }

    // Compare post_residual against mean residual of open bins.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping: reward near-full bins, penalize half-empty ones.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && post_residual < next_item_size) {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let can_host_next_elsewhere = mean_residual >= next_item_size as f64;
                if !can_host_next_elsewhere {
                    score += 55.0;
                }
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            // Stranding justification: opening a fresh bin is worthwhile when
            // the item would strand its host in a wide dead zone while a
            // roomy bin could absorb it with usable slack left over.
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            // Fresh-bin appeal grows when the fleet mean residual is deep in
            // the dead zone and the current fit is mediocre.
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            // NEW: when the fleet is heavily fragmented (many bins whose mean
            // residual cannot even host the next item), a clean bin becomes a
            // consolidation anchor — discount the opening penalty further.
            let stranded_fleet = mean_residual < next_item_size as f64 * 0.9;
            if stranded_fleet && open_bins_count >= 4 && fit_ratio < 0.7 {
                score -= 22.0 * remaining_frac;
            }
