    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Exact k-chain lookahead.
    if next_item_size > 0 && post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k * next_item_size as u32 <= bin_capacity {
            score -= 6.0 * (k.min(5) as f64 - 2.0);
        }
    }

    // Split-fit insurance.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // Dead-zone floor lift — residue just above the next item but below the
    // mean residual is likely to strand next; quadratic penalty refined.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            let lift = 1.0 - slack / mean_residual;
            score += 5.5 * lift * lift * remaining_frac;
        }
    }

    // Perfect-fit ceiling — close with zero waste when others can host next.
    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // NEW: compaction gravity — among bins that can host the item, prefer the
    // one whose post-residual is closest to the fleet mean residual only when
    // that mean is small; when the mean is large, instead prefer the tightest
    // post-residual (minimizing leftover space) to squeeze dead zones shut.
    if bin_residual != bin_capacity && open_bins_count >= 2 && post_residual > 0 {
        let pr = post_residual as f64;
        if mean_residual < 0.15 * cap {
            score -= (cap - pr) * 0.08;
        } else if pr < mean_residual {
            score -= 3.0 * (1.0 - pr / mean_residual.max(1.0));
        }
    }

    // NEW: residual half-life — a post-residual that is an exact divisor
    // window for common small items (1..=10) is a compaction asset; reward
    // proportionally to how many sizes it can still host.
    if bin_residual != bin_capacity && post_residual > 0 {
        let hostable = (post_residual.min(10)) as f64;
        if hostable >= 1.0 {
            score -= 1.2 * hostable * remaining_frac;
        }
    }

    score
}

