        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        // Three-step anticipation: reward residues that are (near) exact
        // multiples of the next size — a chain of same-size fills closes well.
        if after_next >= next_item_size {
            let rem = after_next % next_item_size.max(1);
            if rem == 0 {
                score -= 8.0;
            } else if rem <= 3 {
                score -= 4.0;
            }
