        } else {
            score += 3.0 * (dev / cap);
        }
    }

    // Oversized-item preemption: only bins hosting BOTH current and next
    // items are worth filling when the next item is large.
    if next_item_size as f64 > 0.45 * cap && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if fitting_bins_count >= 2 {
            score += 25.0;
        }
    }

    // COMBINED: dead-zone floor lift — residue just above the next item but
    // below the fleet mean slack is likely to strand next; couple with the
    // exact double-fill window for sharper lookahead.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Perfect-fit ceiling: close with zero waste when alternatives exist.
    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // Exact k-chain lookahead.
    if next_item_size > 0 && post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k * next_item_size as u32 <= bin_capacity {
            score -= 6.0 * (k.min(5) as f64 - 2.0);
        }
    }

    // Split-fit insurance.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // NEW: quadratic compaction gradient — reward placements whose
    // post_residual approaches zero smoothly, so near-closure bins are
    // always preferred over leaving a mid-sized residue, scaled by how
    // much of the stream remains to exploit the closure.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let frac_full = 1.0 - pr / cap;
        score -= 6.0 * frac_full * frac_full * (0.5 + remaining_frac);
    }

    score
}

