            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        // Three-step anticipation: residues that are (near) exact multiples
        // of the next size can be closed by a chain of same-size fills.
        if after_next >= next_item_size {
            let rem = after_next % next_item_size.max(1);
            if rem == 0 {
