                && mean_residual < next_item_size as f64
                && fit_ratio < 0.9
                && remaining_frac > 0.35
            {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            // REFINEMENT: fresh-bin appeal should also scale with how much of
            // the fleet cannot host the CURRENT item — if the item barely fits
            // anywhere, a fresh bin keeps residual structure intact.
            if fitting_bins_count <= 2 && fit_ratio > 0.9 && remaining_frac > 0.3 {
                score -= 20.0 * remaining_frac;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer placements leaving the most
    // usable remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement — residue reachable by the next item is
    // much less dead than residue below it; scale the gap quadratically.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Exact k-chain lookahead.
    if next_item_size > 0 && post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k * next_item_size as u32 <= bin_capacity {
            score -= 6.0 * (k.min(5) as f64 - 2.0);
        }
    }

    // Split-fit insurance.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // Dead-zone floor lift — residue just above the next item but below the
    // mean residual is likely to strand next; penalize the sub-mean gap.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Perfect-fit ceiling — never hesitate to close with zero waste.
    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // Two-chain packing — reward placements that leave room for the next
    // item AND then a second copy of it (exact 2x chain).
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
        let slack2 = post_residual - 2 * next_item_size;
        if slack2 <= 4 {
            score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
        }
    }

    // Bin-pair complementarity — prefer placements whose post_residual
    // complements the mean residual to roughly a full capacity split.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone width guard — residue in [next+1, next+8] is the worst band.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // NEW: residual utility index — grade post_residual by how many copies of
    // the next item it can still host, with a mild convexity bonus so that
    // bins able to host 2+ future items are preferred over marginal hosts.
    if next_item_size > 0 && bin_residual != bin_capacity {
        let hosts = (post_residual / next_item_size.max(1)) as f64;
        if hosts >= 1.0 {
            score -= 6.0 * (hosts.min(4.0) - 1.0) * (0.4 + 0.6 * remaining_frac);
        }
    }

    // NEW: fleet-dead-zone coordination — when the mean residual sits in the
    // dead zone (below the next item), reward placements that either keep
    // their residual above the dead zone or close a bin entirely, so the
    // fleet converges on usable residual levels.
    if next_item_size > 0 && open_bins_count >= 2 && bin_residual != bin_capacity {
        let ns = next_item_size as f64;
        if mean_residual < ns {
            let pr = post_residual as f64;
            if pr >= ns {
                score -= 9.0 * (1.0 - mean_residual / ns);
            } else {
                score += 9.0 * (1.0 - pr / ns.max(1.0));
            }
        }
    }

    // NEW: tight-fit preservation — when the current fit is very tight
    // (fit_ratio near 1), a small extra bonus scaled by how rare such fits
    // are among fitting bins encourages harvesting exact fits immediately.
    if fit_ratio > 0.95 && fitting_bins_count >= 2 && bin_residual != bin_capacity {
        score -= 10.0 * (fit_ratio - 0.95) * 20.0 * remaining_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
