        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // NEW: exact-fit anticipation — when the current item exactly halves the
    // bin, a same-size follow-up is likely; reward leaving a perfect mirror.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // NEW: dead-zone depth against fleet capability — residue that no other
    // open bin could absorb (below the smallest plausible follow-up) is
    // effectively lost capacity; scale the penalty with stream remaining.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    score
}

