            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let can_host_next_elsewhere = mean_residual >= next_item_size as f64;
                if !can_host_next_elsewhere {
                    score += 55.0;
                }
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            // When open bins are collectively roomy enough to absorb both
            // this item and the next, opening a fresh bin is wasteful.
            if next_item_size > 0
                && mean_residual >= (item_size as f64 + next_item_size as f64)
            {
                score += 90.0;
            }
            // Fresh-bin appeal also scales with how many bins could host the
            // item but would end up nearly empty — consolidation beats sprawl.
            if open_bins_count > 5
                && fit_ratio < 0.7
                && mean_residual > item_size as f64
                && remaining_frac > 0.25
            {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length and how well the item
    // itself could sink into such residue elsewhere.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer placements leaving the most
    // usable remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap — two consecutive placements can close the bin.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement — residue reachable by next item is far
    // less dead than residue just below it.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation — bins with residue in the
    // [next, next*3] window are prime hosts for a chain of small fills.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation — preserve large usable residue so late
    // medium items still have homes (reduces forced new bins).
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity — smooth gradient bonus for bins one small item
    // away from closing.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Residual-band pairing — bins whose post-residual sits close to the
    // fleet mean keep the residual distribution compact; outliers strand.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev < 0.5 * mean_residual.max(4.0) {
            score -= 5.0 * (1.0 - dev / (0.5 * mean_residual.max(4.0)));
        } else {
            score += 3.0 * (dev / cap);
        }
    }

    // Oversized-item preemption — when the next item is large, only bins
    // that can host BOTH current and next items are worth filling.
    if next_item_size as f64 > 0.45 * cap && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if fitting_bins_count >= 2 {
            score += 25.0;
        }
    }

    // Exact-fit anticipation — a same-size follow-up is likely after the
    // current item exactly halves the bin; reward leaving a perfect mirror.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Dead-zone depth against fleet capability — residue no other open bin
    // could absorb is effectively lost capacity; scale with stream remaining.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    // NEW: dead-space compaction — when several bins can host the item,
    // prefer the one whose post-residual is closest to being exactly
    // divisible by the smallest plausible follow-up size, so residual
    // space stays reusable rather than fragmenting into dead slivers.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity && post_residual > 0 {
        let unit = next_item_size.max(1) as f64;
        let pr = post_residual as f64;
        let rem = pr % unit;
        let dist = rem.min(unit - rem) / unit;
        if dist < 0.12 {
            score -= 6.0 * (1.0 - dist / 0.12) * (0.4 + remaining_frac);
        } else if pr < unit {
            score += 5.0 * (1.0 - pr / unit) * remaining_frac;
        }
    }

    // NEW: fleet-level compaction — when the fleet is crowded and mean
    // residual is small, tighten the preference toward the bin that keeps
    // post_residual nearest to zero, squeezing out residual dead space.
    if open_bins_count >= 6 && mean_residual < 0.15 * cap && bin_residual != bin_capacity {
        score += (post_residual as f64 / cap) * 22.0 * remaining_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened around the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.35;
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
    }

    // Two-step lookahead: discourage tiny unusable slivers.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
    }

    // Compare post_residual against mean residual of open bins.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && post_residual < next_item_size) {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let can_host_next_elsewhere = mean_residual >= next_item_size as f64;
                if !can_host_next_elsewhere {
                    score += 55.0;
                }
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0
                && mean_residual < next_item_size as f64
                && fit_ratio < 0.9
                && remaining_frac > 0.35
            {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5
                && fit_ratio < 0.7
                && mean_residual > item_size as f64
                && remaining_frac > 0.25
            {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            // NEW: opening a fresh bin is especially wasteful when the fleet
            // already holds enough aggregate residual to absorb this item.
            if open_bins_count >= 3 && mean_residual * open_bins_count as f64 >= item_size as f64 {
                score += 45.0 * remaining_frac;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer placements leaving the most
    // usable remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Exact k-chain lookahead.
    if next_item_size > 0 && post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k * next_item_size as u32 <= bin_capacity {
            score -= 6.0 * (k.min(5) as f64 - 2.0);
        }
    }

    // Split-fit insurance.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Perfect-fit ceiling.
    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // Two-chain packing.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
        let slack2 = post_residual - 2 * next_item_size;
        if slack2 <= 4 {
            score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Exact-fit anticipation — halving a bin invites a same-size follow-up.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Dead-zone depth against fleet capability.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    // NEW: dead-space quanta — penalize residue that is not expressible as a
    // near-multiple of the next item size, since such residue is unlikely to
    // be reclaimed by the anticipated stream; weight by stream remaining.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        let k = (pr / ns).floor();
        let frac_off = pr - k * ns;
        let align_penalty = if frac_off < 0.5 * ns { frac_off / (0.5 * ns) } else { (ns - frac_off) / (0.5 * ns) };
        if align_penalty > 0.55 {
            score += 6.0 * align_penalty * remaining_frac;
        }
    }

    // NEW: residual compaction gradient — among bins that will survive this
    // placement, prefer driving one toward closure rather than leaving many
    // half-full bins; scaled by fleet size and stream progress.
    if bin_residual != bin_capacity && post_residual > 0 {
        let survival = (post_residual as f64 / cap).powi(2);
        score += 9.0 * survival * remaining_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
