    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // Two-chain packing.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
        let slack2 = post_residual - 2 * next_item_size;
        if slack2 <= 4 {
            score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Exact-fit anticipation — when the current item exactly halves the
    // bin, a same-size follow-up is likely; reward leaving a perfect mirror.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Dead-zone depth against fleet capability — residue that no other
    // open bin could absorb (below the smallest plausible follow-up) is
    // effectively lost capacity; scale the penalty with stream remaining.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    // NEW: dead-space compaction via post-fit granularity — reward residues
    // that are near-exact multiples of small plausible follow-up sizes,
    // since such residues are most likely to be fully reclaimed later.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let probe = next_item_size.max(1) as f64;
        let k = (pr / probe).floor();
        if k >= 1.0 && pr - k * probe <= 2.0 {
            score -= 6.0 * (1.0 - (pr - k * probe) / 3.0) * remaining_frac;
        }
    }

    // NEW: fleet-level dead-space pressure — when aggregate open slack is
    // already large relative to capacity, penalize placements that leave
    // mid-range residue (neither closed nor highly usable), pushing items
    // into bins where they compact the residue distribution instead.
    if bin_residual != bin_capacity && open_bins_count >= 4 {
        let fleet_slack = mean_residual * open_bins_count as f64;
        if fleet_slack > 1.5 * cap {
            let pr = post_residual as f64;
            if pr > 0.1 * cap && pr < 0.4 * cap {
                score += 10.0 * (fleet_slack / (3.0 * cap)).min(1.0) * remaining_frac;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly (small post_residual).
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 15 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host next item exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here: penalize dead space relative to next item
            let gap = (next_item_size - post_residual) as f64;
            score += 40.0 * (gap / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: prefer leaving near-average residual
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Penalize new-bin candidate slightly unless post_residual pattern is very favorable
    if bin_residual == bin_capacity {
        score += 60.0;
        // open a new bin when no open bin fits well
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    // Late stream: tighten packing, discourage waste
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.35;
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
    }

    // Two-step lookahead: discourage tiny unusable slivers.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        // Three-step anticipation: residues that are (near) exact multiples
        // of next size can be closed by a chain of same-size fills.
        if after_next >= next_item_size {
            let rem = after_next % next_item_size.max(1);
            if rem == 0 {
                score -= 8.0;
            } else if rem <= 3 {
                score -= 4.0;
            }
        }
    }

    // Compare post_residual against mean residual of open bins.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping: reward near-full bins, penalize half-empty ones.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && post_residual < next_item_size) {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let can_host_next_elsewhere = mean_residual >= next_item_size as f64;
                if !can_host_next_elsewhere {
                    score += 55.0;
                }
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            // When open bins are collectively roomy enough to absorb both
            // this item and the next, opening a fresh bin is wasteful.
            if next_item_size > 0
                && mean_residual >= (item_size as f64 + next_item_size as f64)
            {
                score += 90.0;
            }
            if next_item_size > 0
                && mean_residual < next_item_size as f64
                && fit_ratio < 0.9
                && remaining_frac > 0.35
            {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            // Fresh-bin appeal also scales with how many bins could host the
            // item but would end up nearly empty — consolidation beats sprawl.
            if open_bins_count > 5
                && fit_ratio < 0.7
                && mean_residual > item_size as f64
                && remaining_frac > 0.25
            {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length and how well the item
    // itself could sink into such residue elsewhere.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer placements leaving the most
    // usable remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap — two consecutive placements can close the bin.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement — residue reachable by next item is far
    // less dead than residue just below it.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation — bins with residue in the
    // [next, next*3] window are prime hosts for a chain of small fills.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation — preserve large usable residue so late
    // medium items still have homes (reduces forced new bins).
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity — smooth gradient bonus for bins one small item
    // away from closing.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Residual-band pairing — bins whose post-residual sits close to the
    // fleet mean keep the residual distribution compact; outliers strand.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        let dev = (pr - mean_residual).abs();
        if dev < 0.5 * mean_residual.max(4.0) {
            score -= 5.0 * (1.0 - dev / (0.5 * mean_residual.max(4.0)));
        } else {
            score += 3.0 * (dev / cap);
        }
    }

    // Oversized-item preemption — when the next item is large, only bins
    // that can host BOTH current and next items are worth filling.
    if next_item_size as f64 > 0.45 * cap && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if fitting_bins_count >= 2 {
            score += 25.0;
        }
    }

    // Exact-fit anticipation — a same-size follow-up is likely after the
    // current item exactly halves the bin; reward leaving a perfect mirror.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Dead-zone depth against fleet capability — residue no other open bin
    // could absorb is effectively lost capacity; scale with stream remaining.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    // Dead-space compaction — prefer post-residuals nearly divisible by the
    // follow-up size so residual space stays reusable rather than
    // fragmenting into dead slivers.
    if fitting_bins_count >= 2 && bin_residual != bin_capacity && post_residual > 0 {
        let unit = next_item_size.max(1) as f64;
        let pr = post_residual as f64;
        let rem = pr % unit;
        let dist = rem.min(unit - rem) / unit;
        if dist < 0.12 {
            score -= 6.0 * (1.0 - dist / 0.12) * (0.4 + remaining_frac);
        } else if pr < unit {
            score += 5.0 * (1.0 - pr / unit) * remaining_frac;
        }
    }

    // Fleet-level compaction — crowded fleet with small mean residual:
    // squeeze toward the bin that keeps post_residual nearest to zero.
    if open_bins_count >= 6 && mean_residual < 0.15 * cap && bin_residual != bin_capacity {
        score += (post_residual as f64 / cap) * 22.0 * remaining_frac;
    }

    // Split-fit insurance — when the next item exceeds what the fleet can
    // absorb, discourage placements that strand the residue.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // Two-chain packing — reward residues that can host exactly two
    // follow-up fills with minimal slack.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
        let slack2 = post_residual - 2 * next_item_size;
        if slack2 <= 4 {
            score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
        }
    }

    // Bin-pair complementarity — residues that pair with the fleet mean to
    // nearly fill a second bin are valuable consolidation targets.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Perfect-fit ceiling — closing a bin while alternatives exist is prime.
    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // Exact k-chain lookahead — residues that are exact multiples of the
    // next size enable chained closures.
    if next_item_size > 0 && post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k * next_item_size <= bin_capacity {
            score -= 6.0 * (k.min(5) as f64 - 2.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Strong reward when the bin becomes (nearly) perfectly closed.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits into the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra reward for a chain fit with little slack left after next item.
            let after_next = post_residual - next_item_size;
            score -= 10.0 * (1.0 - after_next as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving awkward medium gaps.
            if post_residual >= 10 && post_residual < 40 {
                score += 12.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading across many open bins when mean residual is large:
    // encourage filling bins with high residual first.
    score -= 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, be more selective (avoid many half-empty bins);
    // late in the stream, accept looser fits since future opportunities diminish.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 10.0 * waste_frac;
    score -= progress * 8.0 * waste_frac;

    // New-bin candidate: mildly discourage opening a new bin unless current fits are bad.
    if bin_residual == bin_capacity {
        score += 25.0 + 0.1 * open_bins_count as f64;
        // But if the item is large relative to capacity and residuals are tight,
        // opening fresh can be good — reduce the penalty.
        let tight = mean_residual < item_size as f64 * 0.5;
        if tight {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        // Two-chain packing: exactly two next-items fit with minimal slack.
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Exact double-fill trap.
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        // Small-item stream anticipation.
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        // Dead-zone depth quadratic.
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Exact-fit anticipation: bin halved by current item invites a mirror fill.
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
        score += 40.0 * (1.0 + (10 - post_residual) as f64) * 0.0; // neutralized
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting in the dead zone.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened around the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.35;
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
    }

    // Two-step lookahead: discourage tiny unusable slivers.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
    }

    // Compare post_residual against mean residual of open bins.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && post_residual < next_item_size) {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let can_host_next_elsewhere = mean_residual >= next_item_size as f64;
                if !can_host_next_elsewhere {
                    score += 55.0;
                }
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0
                && mean_residual < next_item_size as f64
                && fit_ratio < 0.9
                && remaining_frac > 0.35
            {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5
                && fit_ratio < 0.7
                && mean_residual > item_size as f64
                && remaining_frac > 0.25
            {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            // NEW: when the fleet's mean residual cannot even host the next
            // item, opening fresh space is cheaper than stranding it; scale
            // with stream remaining so early sprawl is forgiven.
            if next_item_size > 0
                && mean_residual < 0.5 * next_item_size as f64
                && remaining_frac > 0.5
                && open_bins_count < 8
            {
                score -= 20.0 * remaining_frac;
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer placements leaving the most
    // usable remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Exact k-chain lookahead.
    if next_item_size > 0 && post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k * next_item_size as u32 <= bin_capacity {
            score -= 6.0 * (k.min(5) as f64 - 2.0);
        }
    }

    // Split-fit insurance.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Perfect-fit ceiling.
    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // Two-chain packing.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
        let slack2 = post_residual - 2 * next_item_size;
        if slack2 <= 4 {
            score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Exact-fit anticipation — when the current item exactly halves the
    // bin, a same-size follow-up is likely; reward leaving a perfect mirror.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Dead-zone depth against fleet capability — residue that no other
    // open bin could absorb (below the smallest plausible follow-up) is
    // effectively lost capacity; scale the penalty with stream remaining.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    // NEW: fleet-wide dead-space equalization — when this placement would
    // leave a residual far above the fleet mean while other bins are nearly
    // closed, divert the item to balance residuals and reduce variance.
    if open_bins_count >= 4
        && bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual > next_item_size
    {
        let excess = (post_residual as f64 - mean_residual) / cap;
        if excess > 0.15 {
            score += 22.0 * excess * remaining_frac;
        }
    }

    // NEW: triple-chain anticipation — residue that can host the next item
    // twice plus a small remainder is prime consolidation territory; reward
    // proportional to how cleanly it splits.
    if next_item_size > 0 && post_residual >= 2 * next_item_size {
        let leftover = post_residual - 2 * next_item_size;
        if leftover == 0 {
            score -= 16.0 * (0.5 + remaining_frac);
        } else if leftover <= 6 {
            score -= 9.0 * (0.5 + remaining_frac);
        }
    }

    // NEW: near-closure penalty asymmetry — killing a bin that would have
    // closed with the NEXT item wastes a near-complete bin; penalize only
    // when the fleet has room to host the next item instead.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual > 0
        && post_residual < next_item_size
        && (next_item_size - post_residual) <= 5
        && mean_residual >= next_item_size as f64
    {
        score += 12.0 * remaining_frac;
    }

    // NEW: late-stream exact-closure chase — near the end, prefer placements
    // that close bins outright to eliminate residual variance.
    if remaining_frac < 0.3 && bin_residual != bin_capacity && post_residual > 0 {
        let urgency = (0.3 - remaining_frac) / 0.3;
        if post_residual <= 3 {
            score -= 10.0 * urgency;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items.max(1) as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;

    let mut score = r;

    // Smooth non-linear coupling: polynomial in normalized residual weighted by stream progress
    let poly = rn * rn * (1.0 - rn) * 4.0; // peaks at rn=2/3, zero at extremes
    score += (1.0 - t) * 12.0 * poly - t * 8.0 * poly;

    // Penalize large dead space more as stream progresses (fewer chances to fill it)
    score += t * rn * rn * 30.0;

    // Reward tight fits: post_residual close to zero
    if next_item_size > 0 {
        let gap = if (r as u32) >= next_item_size { r - next_item_size as f64 } else { 0.0 };
        score -= 6.0 * (1.0 - gap / cap);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Prefer bins below mean residual (fill emptier bins when many fit)
    score += 2.0 * (mean_residual - r) / cap;

    // New-bin candidate: neutral baseline, slightly penalized so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened around the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0 + (post_residual - next_item_size) as f64 * 0.35;
        let gap = post_residual - next_item_size;
        if gap <= 3 {
            score -= 12.0;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
    }

    // Two-step lookahead: discourage tiny unusable slivers.
    if next_item_size > 0 && post_residual > next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
    }

    // Compare post_residual against mean residual of open bins.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && post_residual < next_item_size) {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size {
                let can_host_next_elsewhere = mean_residual >= next_item_size as f64;
                if !can_host_next_elsewhere {
                    score += 55.0;
                }
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0
                && mean_residual < next_item_size as f64
                && fit_ratio < 0.9
                && remaining_frac > 0.35
            {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            // Fresh-bin appeal also scales with how many bins could
            // host the item but would end up nearly empty — a crowded fleet of
            // shallow bins wastes capacity; consolidation beats sprawl.
            if open_bins_count > 5
                && fit_ratio < 0.7
                && mean_residual > item_size as f64
                && remaining_frac > 0.25
            {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            // REFINED: when the fleet's total slack can absorb several more
            // items, opening a new bin is pure sprawl — deepen the penalty
            // with fleet-wide absorption headroom.
            if open_bins_count > 3 {
                let headroom = mean_residual * open_bins_count as f64;
                if headroom > 3.0 * item_size as f64 {
                    score += 18.0 * ((headroom / (3.0 * item_size as f64)) - 1.0).min(2.0);
                }
            }
        }
    }

    // Tight-fit coupling: prefer bins whose post_residual best matches next item.
    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    // Exact-match bonus: crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Snugness gradient: penalize killing a bin while another could host both.
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    // Dead-space avoidance: tiny unusable residue weighted by remaining stream.
    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Residual-fragmentation guard: residue just below next item strands.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space accounting: penalize residue in the dead zone proportionally
    // to its depth, scaled by remaining stream length.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            score += 10.0 * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Multiplicity-aware consolidation: prefer placements leaving the most
    // usable remainder for the next item (mild quadratic shaping).
    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Exact double-fill trap.
    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Dead-zone depth refinement.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Small-item stream anticipation.
    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Exact k-chain lookahead.
    if next_item_size > 0 && post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
        let k = post_residual / next_item_size;
        if k * next_item_size as u32 <= bin_capacity {
            score -= 6.0 * (k.min(5) as f64 - 2.0);
        }
    }

    // Split-fit insurance.
    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Perfect-fit ceiling.
    if post_residual == 0 && fitting_bins_count >= 2 {
        score -= 25.0;
    }

    // Two-chain packing.
    if next_item_size > 0 && post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
        let slack2 = post_residual - 2 * next_item_size;
        if slack2 <= 4 {
            score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Exact-fit anticipation — when the current item exactly halves the
    // bin, a same-size follow-up is likely; reward leaving a perfect mirror.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Dead-zone depth against fleet capability — residue that no other
    // open bin could absorb (below the smallest plausible follow-up) is
    // effectively lost capacity; scale the penalty with stream remaining.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    // NEW: mid-range residue shaping — residue in the awkward 11–25 band
    // is too big to ignore yet too small for most items; penalize it
    // unless it exactly matches the next item's size, scaled by stream
    // remaining so late-stream residue matters less.
    if bin_residual != bin_capacity && post_residual >= 11 && post_residual <= 25 {
        let awkward = (post_residual as f64 - 10.0) / 15.0;
        if next_item_size > 0 && post_residual == next_item_size {
            // already rewarded above; no extra penalty
        } else if next_item_size > 0 && post_residual > next_item_size {
            score += 5.0 * awkward * remaining_frac;
        } else {
            score += 9.0 * awkward * (0.3 + remaining_frac);
        }
    }

    // NEW: residual merge potential — reward placements whose post_residual
    // could combine with the fleet's mean residual to fill a future bin
    // exactly, encouraging complementary fragmentation instead of waste.
    if open_bins_count >= 2 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 {
            let combo = pr + mean_residual;
            if (combo - cap).abs() <= 6.0 {
                score -= 8.0 * (1.0 - (combo - cap).abs() / 6.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 5 bands.
    let band = post_residual * 5 / bin_capacity; // 0..4
    // Reward small residuals (good packing) with a harmonic penalty ladder.
    score -= 24.0 / (1.0 + band as f64);

    // Exact-fit harmonic classes: post_residual divisible by small moduli
    // means the leftover can pair with many common item sizes later.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 18.0; }
        else if post_residual % 20 == 0 { score -= 14.0; }
        else if post_residual % 25 == 0 { score -= 10.0; }
        else if post_residual % 5 == 0 { score -= 6.0; }
        // Odd unusable crumbs are penalized.
        if post_residual < 10 && post_residual % 2 == 1 { score += 12.0; }
    } else {
        // Perfect fill is ideal.
        score -= 40.0;
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Harmonic class of next item vs leftover: reward clean division.
            let q = post_residual / next_item_size.max(1);
            score -= 8.0 + 6.0 / (1.0 + q as f64);
            if post_residual % next_item_size == 0 { score -= 10.0; }
        } else if next_item_size <= bin_residual {
            // This bin could have held the next item too: mild penalty.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing residuals are large
    // (i.e., current item fits poorly everywhere).
    if bin_residual == bin_capacity {
        let tight = (mean_residual - item_size as f64).abs();
        let pressure = (open_bins_count as f64) * (mean_residual / bin_capacity as f64);
        // Prefer new bin when item is big and open bins are fragmented.
        score += 60.0 - 0.5 * pressure - (item_size as f64) * 0.3;
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 45.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0; // fresh bin can host item + next item together
        }
        let _ = tight;
    }

    // Slight phase bias: later in the stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

