        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Exact-fit anticipation — when the current item exactly halves the
    // bin, a same-size follow-up is likely; reward leaving a perfect mirror.
    if bin_residual != bin_capacity
        && item_size > 0
        && bin_residual == 2 * item_size
        && 2 * item_size <= bin_capacity
    {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Dead-zone depth against fleet capability — residue that no other
    // open bin could absorb is effectively lost capacity; scale the
    // penalty with stream remaining.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && post_residual < next_item_size
        && mean_residual < next_item_size as f64
    {
        score += 8.0 * remaining_frac;
    }

    // NEW: fleet-capable slack shaping — when the fleet's mean residual is
    // small, oversized post-residual slack (beyond what the next item plus
    // a small tolerance needs) is wasted capacity; penalize mildly to push
    // placements toward tighter fits and reduce residual variance.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && open_bins_count >= 2
        && remaining_frac > 0.3
        && mean_residual < 0.25 * cap
    {
        let slack = post_residual.saturating_sub(next_item_size) as f64;
        if slack > 0.3 * cap {
            score += 6.0 * (slack - 0.3 * cap) / cap * (0.5 + remaining_frac);
        }
    }

    // NEW: late-stream exact-closure surge — near the end, prefer the bin
    // whose post-residual is smallest (hardest closure), tightening packing
    // exactly when wasted bins matter most.
    if remaining_frac < 0.25 && bin_residual != bin_capacity && post_residual > 0 {
        score += (post_residual as f64 / cap) * 18.0 * (0.25 - remaining_frac) / 0.25;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
