            // NEW: fresh-bin appeal scales with usable residual value left in
            // the fleet — if open bins still hold absorbable space, delay
            // opening a new one.
            if open_bins_count > 2 && mean_residual >= next_item_size as f64 && remaining_frac > 0.2 {
                score += 20.0 * (mean_residual / next_item_size.max(1) as f64).min(2.5);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // NEW: endgame exact-closure sprint — near the end, prefer placements
    // that close bins completely over leaving any residue.
    if remaining_frac < 0.25 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual == 0 {
            score -= 20.0 * (0.25 - remaining_frac) / 0.25;
        } else if post_residual < next_item_size {
            score += 10.0 * (0.25 - remaining_frac) / 0.25;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio in the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fractional tightness: how well the item fills the bin after placement
    let tightness = post_residual as f64 / bin_capacity as f64; // 0 = perfect fill

    // Strongly reward tight fits (non-linear squashing of small residuals)
    score -= 30.0 * (1.0 - tightness).powf(3.0);

    // Penalize leaving residuals that are too small for typical items
    // (dead space: residual in 1..10 is nearly unusable)
    if post_residual >= 1 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward heavily; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (-slack / 20.0).exp();
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 8.0 * (1.0 - (-miss / 30.0).exp());
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0 + 10.0 * (1.0 - tightness);
    }

    // Global state: many open bins with large mean residual -> encourage consolidation
    let consolidation_pressure = mean_residual / bin_capacity as f64
        * (open_bins_count as f64).ln().max(0.0);
    score -= 5.0 * consolidation_pressure * (1.0 - tightness);

    // Time horizon: early in the stream, prefer keeping residuals flexible (larger);
    // late in the stream, prefer closing bins out tightly.
    score += 10.0 * tightness * (1.0 - progress);      // early: keep bins roomy
    score -= 12.0 * tightness * progress;              // late: reward tight fills extra

    // New-bin candidate handling: opening a new bin is only attractive when
    // no existing bin fits well. Detect via bin_residual == bin_capacity.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, discounted when the item is large
        // (large items waste less of a fresh bin) or when it's early (long horizon).
        let size_frac = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 20.0 * size_frac - 10.0 * (1.0 - progress);
        // If the item leaves a residual that matches the next item, new bin is fine
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Mild penalty per open bin to discourage bin sprawl
    score += 0.5 * open_bins_count as f64 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
