}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = norm_pr * (1.0 - t) + norm_pr * norm_pr * t;
    score = poly * cap;
    // Smooth penalty for large dead space that scales with progress
    let dead = norm_pr * norm_pr * (1.0 - norm_pr);
    score += dead * cap * (0.5 + t);
    // Reward tight fits (small post_residual) more strongly later in stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * t * 10.0;
    // Lookahead: reward if next item fits into post residual (smooth gate)
    if next_item_size > 0 {
        let fits = if (next_item_size as f64) <= pr { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= fits * (1.0 - gap) * (5.0 + 10.0 * t);
        score += (1.0 - fits) * gap * cap * (0.2 + 0.6 * t);
    }
    // Last-chance bin bonus (smooth, avoid hard piecewise)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 1.0 / fitting_bins_count as f64 };
    score -= last_chance * 8.0 * (0.5 + t);
    // Prefer bins with residual below mean (consolidation), smooth
    let diff = (pr - mean_residual) / cap;
    score += diff * diff * 4.0 - diff * 3.0;
    // Slight penalty for opening new bin early in stream
    if bin_residual == bin_capacity {
        score += (1.0 - t) * 15.0 + open_bins_count as f64 * 0.5;
    }
    score
}

