            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Residual-value conservation: mid-size usable residue is valuable while
    // the stream is long.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity: keep pairable leftovers in the fleet.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the new-bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Perfect lookahead fit: placing item here leaves exactly the space
    // the next item needs -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item still fits in the leftover space: mild reward.
    else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }
    // Lookahead item would be blocked: penalize proportionally.
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Harmonic class logic: partition post_residual by capacity fractions
    // and integer division thresholds.
    let quarter = bin_capacity / 4;      // 25
    let half = bin_capacity / 2;         // 50
    let min_item: u32 = 10;

    if post_residual == 0 {
        // Perfect closure: best possible outcome.
        score -= 100.0;
    } else if post_residual < min_item {
        // Dead space below the smallest possible item: unusable waste.
        score += 12.0;
    } else if post_residual < quarter {
        // Small but usable residue: mildly attractive (best-fit flavor).
        score -= 3.0;
    } else if post_residual == half {
        // Exactly half-full residue: a nice harmonic class, keep it.
        score -= 5.0;
    } else if post_residual % half == 0 {
        // Residue is a multiple of half-capacity: structurally good.
        score -= 4.0;
    } else if post_residual % quarter == 0 {
        // Residue is a multiple of quarter-capacity.
        score -= 2.0;
    } else if post_residual > 3 * quarter {
        // Large residue: bin still mostly empty; slightly discourage
        // fragmenting it with a small item unless needed.
        score += (post_residual as f64 - 3.0 * quarter as f64) * 0.1;
    }

    // Last-chance bin: if this is the ONLY bin that can fit the item,
    // strongly favor it over opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is expensive; only make
    // it attractive when no open bin is a decent fit.
    if is_new_bin {
        let open_cost = 30.0;
        // Scale pressure by stream progression: later in the stream,
        // consolidation matters more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = open_cost + 20.0 * progress;
        // If several bins can fit the item, really discourage a new bin.
        if fitting_bins_count >= 1 {
            penalty += 25.0 * (fitting_bins_count as f64);
        }
        // If no open bin fits (fitting_bins_count == 0 counting only
        // open bins), the new bin is the natural choice.
        if fitting_bins_count == 0 {
            penalty -= 60.0;
        }
        // If the item would leave a perfectly harmonic residue in a
        // fresh bin, opening can be reasonable.
        if bin_capacity % item_size.max(1) == 0 {
            penalty -= 8.0;
        }
        score += penalty;
    }

    // Mild tie-breaker toward bins below-average fullness? Prefer bins
    // with residual close to mean (balanced consolidation).
    let diff = (bin_residual as f64 - mean_residual).abs();
    score += diff * 0.05;

    // Slight preference for tighter fits overall (best-fit base already
    // in post_residual); add tiny jitter-free coupling with item size.
    score += (item_size as f64) * 0.01;

    score
}

