    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // NEW: dead-zone width guard — bands of slack just above the next item
    // (1..8 over, item >= 8) tend to strand; penalize late in the stream.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // NEW: avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: minimize leftover space, with a non-linear penalty on large residuals.
    let mut score = pr + 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Perfect-fit reward (smooth polynomial coupling with progress).
    if pr == 0 {
        score -= 60.0 + 30.0 * progress;
    }

    // Penalize small unusable residuals: dead space term (non-linear).
    let dead = (norm_pr - 0.1).max(0.0);
    score += 25.0 * dead * dead * (pr / 100.0);

    // Last-chance bonus: strongly favor the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early or residual waste would be large.
    if bin_residual == bin_capacity {
        let waste_penalty = (pr - mean_residual).abs();
        score += 35.0 + 80.0 * progress * (1.0 - norm_pr) - 0.5 * waste_penalty;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 20.0;
        }
    } else {
        // Lookahead coupling: reward bins whose post-residual fits the next item.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0 * (1.0 - pr / cap);
        } else if next_item_size > post_residual {
            score += 8.0;
        }
    }

    // Mild congestion adjustment: when many bins are open, tighten residual preference.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * norm_pr;

    // Smooth progress-based tightening: as stream progresses, demand tighter fits.
    score *= 1.0 + 0.3 * progress * progress;

    score
}

