    // Residual-fragmentation guard.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // NEW: fleet-residual sweep — if the fleet's mean residual could absorb
    // this item almost as well, prefer the bin whose post_residual best
    // matches the mean, minimizing fleet-wide dead space variance.
    if open_bins_count >= 3 && bin_residual != bin_capacity && mean_residual > 1.0 {
        let drift = (post_residual as f64 - mean_residual).abs() / mean_residual;
        if drift < 0.35 {
