        // NEW: residual left after next placement should ideally be absorbable
        // by the fleet's mean residual; otherwise it is likely dead space.
        if after_next > 0 && open_bins_count >= 2 && (after_next as f64) > mean_residual {
            score += 6.0 * ((after_next as f64 - mean_residual) / cap).min(0.5) * 100.0 * (0.4 + remaining_frac);
        }
        // NEW: reward bins whose post-residual matches the mean residual band,
        // keeping the fleet in a reusable size regime.
        if after_next > 0 && mean_residual > 1.0 {
            let band = ((after_next as f64 - mean_residual) / mean_residual).abs();
            if band < 0.25 {
