            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: after-next residual that still exceeds the mean by a wide band
        // is recoverable for future items — mild extra reward when the fleet is
        // hungry for space (low mean residual).
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) > mean_residual * 2.0 {
            score -= 3.0 * (1.0 - (after_next as f64 / cap).min(1.0)) * remaining_frac;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
