            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item; only
            // open when the fleet is genuinely too tight.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control — when many bins are open early,
            // require the new bin to promise a tight residual (item fills most
            // of it), otherwise prefer squeezing into the fleet.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // NEW: opening a bin leaves residual = cap - item_size; only allow
            // it when that residual is either near-zero (tight fill) or large
            // enough to be reusable by the next item. Mid-size stranded
            // residuals are the main dead-space source, so penalize them.
            if next_item_size > 0 {
                let new_res = cap - item_size as f64;
                if new_res > 4.0 && new_res < next_item_size as f64 {
                    let stranded_frac = 1.0 - new_res / next_item_size as f64;
                    score += 45.0 * stranded_frac * (0.5 + remaining_frac);
                }
                // Reward a fresh bin whose residual exactly chains to next item.
                if new_res == next_item_size as f64 {
                    score -= 60.0;
                }
            }
            // NEW: late-stream compaction — near the end, almost never open a
            // new bin unless it produces a perfect fit.
            if remaining_frac < 0.2 && fit_ratio < 0.95 {
                score += 80.0 * (1.0 - fit_ratio);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space — penalize residuals that neither
    // fit the next item nor can pair with the fleet mean to host it.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // NEW: residual-pairing lookahead — reward residuals that, combined with
    // any plausible fleet residual, could absorb the next two items; penalize
    // residuals that pair with nothing (true dead space) more sharply late.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let pairable = (cap - pr - mean_residual).abs() < 6.0
            || (next_item_size > 0 && (pr + mean_residual - next_item_size as f64).abs() < 4.0);
        if !pairable && pr < 0.35 * cap && remaining_frac < 0.6 {
            score += 5.0 * (1.0 - pr / (0.35 * cap)) * (1.2 - remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: residual that survives both this item and the next one becomes
        // a recoverable slot — reward when it can still host a typical item.
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) >= mean_residual * 0.9 {
            score -= 4.0 * remaining_frac * ((after_next as f64 / mean_residual).min(2.0) - 0.9);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item; only
            // open when the fleet is genuinely too tight.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control — when many bins are open early,
            // require the new bin to promise a tight residual (item fills most
            // of it), otherwise prefer squeezing into the fleet.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // NEW: late-stream sprawl control — near the end, a fresh bin is
            // only worth it if it closes nearly perfectly or the fleet is
            // starved; otherwise squeeze into existing space.
            if remaining_frac < 0.25 && open_bins_count > 2 && fit_ratio < 0.92 {
                score += 60.0 * (0.92 - fit_ratio) * (1.0 - remaining_frac) * 3.0;
            }
            // NEW: if the fleet's mean residual cannot absorb even half the
            // next item, the fleet is starving — soften the sprawl penalty.
            if next_item_size > 0 && mean_residual < next_item_size as f64 * 0.5 && open_bins_count < 8 {
                score -= 30.0 * remaining_frac;
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space — penalize residuals that neither
    // fit the next item nor can pair with the fleet mean to host it.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
        // NEW: reward residuals that pair with the fleet mean to exactly or
        // nearly host the next item (recoverable dead space).
        if pr < next_item_size as f64 && mean_residual > 1.0 && pr + mean_residual >= next_item_size as f64 {
            let surplus = pr + mean_residual - next_item_size as f64;
            score -= 5.0 * (1.0 - (surplus / mean_residual).min(1.0)) * remaining_frac;
        }
    }

    // NEW: endgame compaction — with few items left, prefer residuals that
    // stay large enough to host remaining typical sizes; punish fragments.
    if remaining_frac < 0.2 && bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        if pr > 0.35 * cap && next_item_size > 0 && pr >= next_item_size as f64 {
            score -= 8.0 * (1.0 - remaining_frac * 4.0).max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: harmonic-pair lookahead — reward residuals whose leftover can
        // pair with the fleet mean residual to host the next item exactly.
        if after_next > 0 && mean_residual > 1.0 {
            let pair_gap = ((after_next as f64 + mean_residual) - next_item_size as f64).abs();
            if pair_gap <= 3.0 {
                score -= 9.0 * (1.0 - pair_gap / 4.0) * (0.5 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            // NEW: also treat gaps recoverable by the *next* item as live space.
            let next_absorb = next_item_size > 0 && post_residual >= next_item_size;
            let w = if fleet_absorb { 0.55 } else if next_absorb { 0.7 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control — require the new bin to promise a
            // tight residual (item fills most of it), otherwise squeeze.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // NEW: allow opening when the fresh bin's residual would be a
            // clean multiple of the next item (predictable chain packing).
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
            {
                score -= 30.0 * (0.4 + remaining_frac);
            }
            // NEW: late-stream — when few items remain, a new bin only pays
            // off if this item nearly fills it; otherwise compact harder.
            if remaining_frac < 0.2 && fit_ratio < 0.9 {
                score += 60.0 * (0.9 - fit_ratio);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space — penalize residuals that neither
    // fit the next item nor can pair with the fleet mean to host it.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // NEW: endgame compaction — with very few items left, strongly prefer
    // bins whose post-residual exactly matches any remaining small item class.
    if remaining_frac < 0.1 && next_item_size > 0 && post_residual > 0 {
        if post_residual == next_item_size {
            score -= 15.0 * (1.0 - remaining_frac);
        } else if post_residual < next_item_size {
            score += 5.0 * (1.0 - remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened around the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        // Two-chain packing: exactly two next-items fit with minimal slack.
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        // Pairability — reward residuals that can later pair with the
        // fleet mean to host the next item even if they cannot host it alone.
        if open_bins_count >= 3 && after_next > 0 {
            let pairable = (after_next as f64 + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 6.0 * (1.0 - pairable / (0.1 * cap)) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Compare post_residual against mean residual of open bins.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && item_size > 0 && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        if bin_residual != bin_capacity && mean_residual < next_item_size as f64 {
            score += 8.0 * remaining_frac;
        }
    }

    // Dead-space accounting with fleet-absorbability weighting.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Two-step lookahead on dead space — penalize residuals that neither
    // fit the next item nor can pair with the fleet mean to host it.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Mid-stream consolidation — crowded fleet with tight residuals: prefer
    // bins whose post-residual stays absorbable by the fleet mean.
    if open_bins_count > 4 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0 && pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score -= 6.0 * remaining_frac;
        }
    }

    // MUTATION: dual-horizon compaction — when the fleet can host both this
    // item and the next, reward bins that leave a mean-absorbable residual
    // after the next item lands, tightening overall fleet compaction.
    if open_bins_count > 2
        && bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && mean_residual >= item_size as f64
    {
        let after_next = post_residual - next_item_size;
        if after_next > 0 && (after_next as f64) <= mean_residual * 1.2 {
            score -= 9.0 * (1.0 - after_next as f64 / (mean_residual * 1.2)) * (0.3 + remaining_frac);
        }
    }

    // MUTATION: endgame squeeze — near the end, every residual that can host
    // the next item is precious; penalize wasting a hostable residual on a
    // poor fit while plenty of stream remains to fill it.
    if progress > 0.6 && next_item_size > 0 && post_residual >= next_item_size && fit_ratio < 0.7 {
        score += 10.0 * (0.7 - fit_ratio) * (progress - 0.6) * 5.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control — require the new bin to promise
            // a tight residual, otherwise prefer squeezing into the fleet.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Late-stream sprawl control — near the end, opening a fresh bin
            // only pays off if it will be nearly filled; otherwise squeeze
            // into the fleet to keep the bin count down.
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // MUTATION: new-bin two-step promise — only open a fresh bin if
            // its post-residual can still host the next item or pair with
            // the fleet mean to do so; otherwise prefer the fleet.
            if next_item_size > 0 && fit_ratio < 0.9 {
                let pr = post_residual as f64;
                let hosts_next = pr >= next_item_size as f64;
                let pairs_next = pr + mean_residual >= next_item_size as f64;
                if !hosts_next && !pairs_next && open_bins_count > 2 {
                    score += 45.0 * (0.5 + remaining_frac);
                }
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // NEW: dead-space recoverability via fleet composition — a leftover is only
    // truly dead if it is smaller than both the next item AND the fleet mean
    // cannot pair with it to host anything useful later. Weight by remaining
    // stream length since late-stream dead space matters less.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        // NEW: penalize leftovers that are "almost but not quite" hostable by
        // the fleet mean — these are the most wasteful near-miss gaps.
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item; only
            // open when the fleet is genuinely too tight.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control — when many bins are open early,
            // require the new bin to promise a tight residual (item fills most
            // of it), otherwise prefer squeezing into the fleet.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // NEW: when the fleet's mean residual is small (tight fleet), a new
            // bin is only justified if this item leaves a residual that pairs
            // well with the fleet mean (i.e. mean + post can host a mid item).
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // NEW: late-stream, strongly prefer squeezing into existing bins —
            // a fresh bin late almost never pays for itself.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space — penalize residuals that neither
    // fit the next item nor can pair with the fleet mean to host it.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // NEW: reward residuals that exactly complement the fleet mean into a
    // full bin — this actively closes bins by pairing leftovers.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Exact-fit anticipation.
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // NEW: dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Tight-fleet pairing requirement for a new bin.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream: fresh bins almost never pay for themselves.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Divisible residue chains.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // NEW: reward residuals that exactly complement the fleet mean into a
    // full bin — actively closes bins by pairing leftovers.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // NEW: near-closure squeeze — residuals within a few units of hosting the
    // next item pair with the fleet mean; keep them alive for pairing.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let deficit = (next_item_size - post_residual) as f64;
        if deficit <= mean_residual + 4.0 {
            score -= 6.0 * (1.0 - deficit / (mean_residual + 4.0)) * remaining_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let cap = bin_capacity as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Sharpened snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 && bin_residual != bin_capacity {
        score += 40.0 * (1.0 + (10 - post_residual) as f64);
        score += 6.0 * remaining_frac;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain quality and sliver shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if fitting_bins_count >= 2 && (after_next as f64) < 0.2 * cap {
            score -= 8.0 * (1.0 - after_next as f64 / (0.2 * cap));
        }
        // Small-item stream anticipation.
        if next_item_size <= 20 {
            let chain_cap = 3 * next_item_size;
            if post_residual <= chain_cap {
                let tightness = 1.0 - after_next as f64 / (chain_cap - next_item_size) as f64;
                score -= 10.0 * tightness * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
            score -= 22.0;
        }
        // Divisible residue predicts multi-item chains.
        if post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
            let k = post_residual / next_item_size;
            if k * next_item_size <= bin_capacity {
                score -= 6.0 * (k.min(5) as f64 - 2.0);
            }
        }
        if post_residual < 2 * next_item_size {
            let frac = after_next as f64 / next_item_size as f64;
            if frac > 0.6 {
                score += 9.0 * frac;
            }
        }
        // Two-chain packing.
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Dead-zone width guard.
        let band = after_next;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
        // Slack below mean residual is likely to strand.
        if mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
        if next_item_size as f64 > mean_residual.max(1.0) * 1.6 && fitting_bins_count >= 2 {
            score += 8.0;
        }
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }
    // Double-fill complement on the pre-placement residual.
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation pressure toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0
                && mean_residual < next_item_size as f64
                && fit_ratio < 0.9
                && remaining_frac > 0.35
            {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0
                && mean_residual >= next_item_size as f64
            {
                score += 20.0;
            }
            // Refuse a fresh bin when the fleet's mean residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse when the fleet holds recoverable mid-size residuals that
            // could individually host this item.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Tight fleet: new bin must leave a residual that pairs with the fleet.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream: fresh bin almost never pays for itself.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    // Dead-zone accounting with fleet-absorbability weighting: a leftover is
    // only truly dead if the fleet mean cannot pair with it.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if post_residual as f64 > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Sub-mean slack penalty.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Dead-zone depth refinement relative to the next item.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
            // Two-step dead space: neither fits next item nor pairs with fleet mean.
            if pr + mean_residual < ns {
                let deficit = ns - pr - mean_residual;
                score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
            }
            // Near-miss pairing: almost recoverable via fleet mean.
            if mean_residual >= 1.0 && pr + mean_residual >= ns - 6.0 {
                let near_miss = 1.0 - ((ns - pr - mean_residual).max(0.0) / 6.0);
                score += 4.0 * near_miss * remaining_frac;
            }
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Residual-value conservation: mid-size usable residue is valuable.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity: keep pairable leftovers in the fleet.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: residual that exactly equals the fleet mean after hosting the
        // next item means a sibling bin can mirror it — pairable closure.
        if after_next > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
            let d = ((after_next as f64) - mean_residual).abs();
            if d <= 4.0 {
                score -= 6.0 * (1.0 - d / 5.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition — a leftover is only
    // truly dead if it is smaller than both the next item AND the fleet mean
    // cannot pair with it to host anything useful later.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        // Penalize leftovers that are "almost but not quite" hostable by
        // the fleet mean — these are the most wasteful near-miss gaps.
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Tight fleet: new bin only justified if its residual pairs well
            // with the fleet mean.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream, strongly prefer squeezing into existing bins.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // NEW: a fresh bin is only attractive if its leftover residual is
            // itself "productive" — i.e. the fleet mean plus this leftover can
            // still host a mid-size item later. Penalize fresh bins whose
            // post-residual is a loner (below mean and below any plausible
            // small item), since that guarantees dead space at birth.
            if open_bins_count > 2 && post_residual > 0 && remaining_frac > 0.15 {
                let pr = post_residual as f64;
                let loner = pr < mean_residual * 0.6 && pr < 8.0;
                if loner {
                    score += 20.0 * (1.0 - pr / 8.0) * (0.5 + remaining_frac);
                }
                // Conversely reward fresh bins whose residual complements the
                // mean into a nearly full bin (pairable closure at birth).
                if mean_residual >= 1.0 && ((pr + mean_residual - cap).abs() <= 6.0) {
                    score -= 25.0 * remaining_frac;
                }
            }
            // NEW: mid-stream, prefer opening a bin whose residual sits in the
            // "sweet spot" band (25–50% of capacity) that the fleet mean
            // cannot currently reach — these become useful hosts for mid items.
            if remaining_frac > 0.3 && remaining_frac < 0.85 && post_residual > 0 {
                let pr = post_residual as f64;
                if pr >= 0.25 * cap && pr <= 0.5 * cap && mean_residual < 0.2 * cap {
                    score -= 18.0 * remaining_frac;
                }
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // NEW: late-stream terminal compaction — with few items left, prioritize
    // minimizing leftover space directly and prefer bins whose post-residual
    // can host the next item exactly; otherwise prefer the smallest gap.
    if remaining_frac < 0.35 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 {
            // This bin strands the next item — mild penalty scaled by gap.
            score += 5.0 * ((next_item_size - post_residual) as f64 / cap).min(1.0) * (1.0 - remaining_frac);
        } else if pr == next_item_size as f64 {
            score -= 10.0 * (1.0 - remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition — a leftover is only
    // truly dead if it is smaller than both the next item AND the fleet mean
    // cannot pair with it to host anything useful later. Weight by remaining
    // stream length since late-stream dead space matters less.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        // Penalize leftovers that are "almost but not quite" hostable by
        // the fleet mean — these are the most wasteful near-miss gaps.
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item; only
            // open when the fleet is genuinely too tight.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control — when many bins are open early,
            // require the new bin to promise a tight residual (item fills most
            // of it), otherwise prefer squeezing into the fleet.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // When the fleet's mean residual is small (tight fleet), a new
            // bin is only justified if this item leaves a residual that pairs
            // well with the fleet mean (i.e. mean + post can host a mid item).
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream, strongly prefer squeezing into existing bins —
            // a fresh bin late almost never pays for itself.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // NEW: a new bin's residual should itself be pairable with the
            // fleet mean to close a future bin; if post + mean overshoots cap
            // by a small amount (near-complement), reward opening it since it
            // enables fleet-level pairing, otherwise penalize an oddball gap.
            if open_bins_count >= 3 && mean_residual >= 1.0 {
                let sum = post_residual as f64 + mean_residual;
                if (sum - cap).abs() <= 4.0 {
                    score -= 45.0 * (1.0 - (sum - cap).abs() / 5.0);
                } else if sum > cap + 4.0 && post_residual as f64 > 0.3 * cap {
                    score += 25.0;
                }
            }
            // NEW: when the fleet mean residual is large (loose fleet with lots
            // of recoverable space), opening a new bin wastes that recoverable
            // space — push harder toward the fleet.
            if mean_residual > 0.3 * cap && open_bins_count > 2 && fit_ratio < 0.8 {
                score += 30.0 * ((mean_residual / cap - 0.3) * 3.3).min(1.0) * (1.0 - fit_ratio);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space — penalize residuals that neither
    // fit the next item nor can pair with the fleet mean to host it.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a
    // full bin — this actively closes bins by pairing leftovers.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // NEW: residual-chaining reward — a leftover that can host the next item
    // AND whose remainder then pairs with the fleet mean to near-close a bin
    // is a compaction triple-win; reward it progressively.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size && open_bins_count >= 2 && mean_residual >= 1.0 {
        let after_next = post_residual - next_item_size;
        let chain = after_next as f64 + mean_residual;
        if (chain - cap).abs() <= 6.0 {
            score -= 12.0 * (1.0 - (chain - cap).abs() / 7.0) * (0.5 + remaining_frac);
        }
        // NEW: penalize residuals that after hosting the next item leave a
        // gap that is too small for anything useful (sub-8 units) — these
        // strand capacity that no future small item can reliably fill.
        if after_next > 0 && after_next < 8 && remaining_frac > 0.3 {
            score += 6.0 * (1.0 - after_next as f64 / 8.0) * remaining_frac;
        }
    }

    // NEW: fleet-tightness adaptive fit bonus — when many bins compete for
    // placement (high fitting_bins_count), prefer the bin whose post residual
    // is closest to the fleet mean (keeps residuals uniform, maximizing
    // future pairing probability across the fleet).
    if bin_residual != bin_capacity && fitting_bins_count >= 3 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let dev = (post_residual as f64 - mean_residual).abs();
        if dev < 0.25 * cap {
            score -= 5.0 * (1.0 - dev / (0.25 * cap)) * remaining_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: reward residuals that can still host a *third* item from the
        // fleet mean pool — a post-residual that pairs with mean_residual to
        // host a mid-size item is recoverable, not dead.
        let an = after_next as f64;
        if an > 0.0 && mean_residual >= 1.0 && open_bins_count >= 2 {
            let hostable = an + mean_residual;
            if hostable >= 0.25 * cap && an < 0.25 * cap {
                score -= 6.0 * (an / (0.25 * cap)) * remaining_frac;
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition — a leftover is only
    // truly dead if it is smaller than both the next item AND the fleet mean
    // cannot pair with it to host anything useful later.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        // Penalize leftovers that are "almost but not quite" hostable by
        // the fleet mean — these are the most wasteful near-miss gaps.
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Tight-fleet pairing check for the new bin's leftover.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream: squeezing into existing bins almost always wins.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // NEW: a fresh bin is justified when its leftover will exactly
            // complement the fleet mean into a full bin (bin-closing move).
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 4.0
            {
                score -= 45.0 * remaining_frac;
            }
            // NEW: penalize a fresh bin whose leftover is stranded relative to
            // the fleet — nothing in the mean pool can ever pair with it.
            if open_bins_count >= 2
                && post_residual > 0
                && mean_residual >= 1.0
                && (post_residual as f64 + mean_residual) < 0.2 * cap
                && post_residual as f64 > mean_residual * 2.0
            {
                score += 25.0 * (0.5 + remaining_frac);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // NEW: graded reward for post-residuals close to the next item — near
    // matches leave tiny slack that subsequent small items can still absorb.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let overshoot = (post_residual - next_item_size) as f64;
        if overshoot <= 2.0 {
            score -= 10.0 * (1.0 - overshoot / 3.0) * (0.4 + remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: after placing this item AND the next, the leftover should still
        // be pairable with the fleet mean — otherwise we're deferring waste.
        if after_next > 0 && mean_residual >= 1.0 && (after_next as f64) < mean_residual {
            score += 3.0 * (1.0 - after_next as f64 / mean_residual) * remaining_frac;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // NEW: a fresh bin is only worth opening if its post-placement
            // residual is large enough to plausibly absorb future items; a
            // new bin that immediately strands at a tiny residual is sprawl.
            if post_residual > 0
                && (post_residual as f64) < 0.2 * cap
                && open_bins_count > 1
                && remaining_frac > 0.15
            {
                score += 18.0 * (1.0 - post_residual as f64 / (0.2 * cap)) * remaining_frac;
            }
            // NEW: prefer a new bin when the fleet's mean residual is so small
            // that it cannot host this item at all (squeezing would strand).
            if open_bins_count > 1
                && next_item_size > 0
                && mean_residual + 1.0 < item_size as f64
                && fit_ratio < 0.95
                && remaining_frac > 0.3
            {
                score -= 20.0 * remaining_frac;
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // NEW: reward residuals that complement the NEXT item's size into a full
    // bin — closing bins via two-item pairing, not just fleet-mean pairing.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && next_item_size != item_size
    {
        let sum = post_residual as f64 + next_item_size as f64;
        if (sum - cap).abs() <= 4.0 {
            score -= 10.0 * (1.0 - (sum - cap).abs() / 5.0) * (0.5 + remaining_frac);
        }
    }

    // NEW: penalize residuals that sit just below a mid-size threshold —
    // gaps in the 20..35 range are the most common stranded dead space;
    // nudge selection toward bins avoiding that band unless pairable.
    if bin_residual != bin_capacity && post_residual >= 20 && post_residual <= 35 {
        let pairable = mean_residual >= 1.0 && (post_residual as f64 + mean_residual) >= 0.5 * cap;
        if !pairable {
            score += 5.0 * remaining_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: after placing this item AND the next, can the fleet mean still
        // top off the bin? A residual that pairs with mean_residual into a
        // near-full state is worth chasing.
        if open_bins_count >= 2 && mean_residual >= 1.0 {
            let pr = post_residual as f64;
            if pr > mean_residual && (pr + mean_residual) <= cap {
                score -= 5.0 * (1.0 - (cap - pr - mean_residual) / cap) * remaining_frac;
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Refuse a fresh bin when the fleet holds several recoverable
            // mid-size residuals that could individually host this item.
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            // Early-stream sprawl control.
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Tight-fleet check: a new bin must leave a residual that pairs
            // well with the fleet mean.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream: strongly prefer squeezing into existing bins.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // NEW: mid-stream sprawl gate — before opening a bin, require the
            // new bin's own post-residual to be small enough that the next
            // item (or the fleet mean) can still use it; otherwise the fresh
            // bin just becomes another dead-space sink.
            if open_bins_count > 3
                && remaining_frac > 0.15
                && next_item_size > 0
                && post_residual > 0
                && post_residual < next_item_size
                && post_residual as f64 + mean_residual < next_item_size as f64
            {
                score += 45.0 * remaining_frac;
            }
            // NEW: reward opening a fresh bin when the item is large enough
            // that the leftover residual is exactly the kind of gap the fleet
            // mean can absorb (post + mean ≈ a mid-size item slot).
            if open_bins_count > 3
                && next_item_size > 0
                && post_residual > 0
                && post_residual as f64 >= mean_residual
                && (post_residual as f64 + mean_residual) >= next_item_size as f64
                && fit_ratio > 0.6
            {
                score -= 20.0 * fit_ratio * remaining_frac;
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // NEW: strong late-stream compaction — when few items remain, residuals
    // that can still absorb the next item are disproportionately valuable,
    // while residuals that cannot are nearly worthless. Sharpen both sides.
    if remaining_frac < 0.1 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - remaining_frac / 0.1);
        } else {
            score += 10.0 * (1.0 - remaining_frac / 0.1);
        }
    }

    score
}

