        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin when the new bin's own post residual would
            // itself be dead space (too small for the next item and below the
            // fleet mean's pairing reach) — the fresh bin would immediately
            // become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // NEW: a fresh bin is more acceptable when the item placed leaves
            // a post residual that is an exact multiple of the next item —
            // the new bin can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination — for open bins, a post residual
    // that is smaller than the fleet mean's smallest useful payload is nearly
    // unrecoverable. Scale the penalty with how far below the mean it sits,
    // but only mid-stream where recovery still matters.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        // Reward leaving a residual that is itself a "perfect host" — large
        // enough to fit the next item with minimal slack.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // NEW: penalize open-bin placements that strand a residual just below a
    // common small-item size band (1..=10) when no small items are expected —
    // inferred from the next item being large.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // NEW: chain-closure bonus — prefer placements whose post residual can
    // absorb the next item AND whose remaining slack matches the fleet mean
    // residual closely, so the next-next placement can also close a bin.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // NEW: early-stream consolidation — when few bins are open and the stream
    // is young, mildly prefer bins whose post residual stays above the fleet
    // mean so future medium items still have hosts; below-mean leftovers
    // early on are the primary source of dead space.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let cap = bin_capacity as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Perfect fit rewards.
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }

    // Dead-space penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual <= 10 && bin_residual != bin_capacity {
        score += 40.0 * (1.0 + (10 - post_residual) as f64);
        score += 6.0 * remaining_frac;
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if fitting_bins_count >= 2 && (after_next as f64) < 0.2 * cap {
            score -= 8.0 * (1.0 - after_next as f64 / (0.2 * cap));
        }
        // Small-item stream anticipation.
        if next_item_size <= 20 {
            let chain_cap = 3 * next_item_size;
            if post_residual <= chain_cap {
                let tightness = 1.0 - after_next as f64 / (chain_cap - next_item_size).max(1) as f64;
                score -= 10.0 * tightness * (0.5 + remaining_frac);
            }
        }
        // Exact double-fill trap.
        if post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
            score -= 22.0;
        }
        // Divisible residue predicts multi-item chains.
        if post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
            let k = post_residual / next_item_size;
            if k * next_item_size <= bin_capacity {
                score -= 6.0 * (k.min(5) as f64 - 2.0);
            }
        }
        // Chain-closure bonus: slack matching fleet mean enables next closure.
        if bin_residual != bin_capacity && open_bins_count >= 2 && mean_residual > 1.0 {
            let an = after_next as f64;
            let closeness = (an - mean_residual).abs();
            if closeness <= 5.0 && an >= 1.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
        // Avoid stranding medium residue when a near-exact alternative exists.
        if post_residual < 2 * next_item_size {
            let frac = after_next as f64 / next_item_size as f64;
            if frac > 0.6 {
                score += 9.0 * frac;
            }
        }
        // Two-chain packing.
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Dead-zone width guard.
        let band = after_next;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    } else if next_item_size > 0 {
        // Dead space that cannot host the next item.
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
        if next_item_size as f64 > mean_residual.max(1.0) * 1.6 && fitting_bins_count >= 2 {
            score += 8.0;
        }
        // Dead-space recoverability via fleet composition.
        if bin_residual != bin_capacity && post_residual > 0 && remaining_frac > 0.2 {
            let pr = post_residual as f64;
            let pair_ok = mean_residual >= 1.0 && pr + mean_residual >= next_item_size as f64;
            if !pair_ok {
                let deficit = (next_item_size as f64 - pr).max(1.0);
                score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
            }
        }
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            // Refuse a fresh bin whose post residual would itself be dead space.
            if open_bins_count > 2 && next_item_size > 0 && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Fresh bin whose post residual pairs with fleet mean promises closure.
            if open_bins_count >= 2 && mean_residual >= 1.0 && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin with exact multiple post residual closes in consecutive steps.
            if next_item_size > 0 && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Residual-value conservation.
            if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0
                && mean_residual >= next_item_size as f64
            {
                score += 20.0;
            }
            // Late-stream: keep using open bins.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    // Dead-zone accounting.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if post_residual as f64 > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Sub-mean slack penalty.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Dead-zone depth refinement.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Residual-value conservation: mid-size usable residue is valuable.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
        // Perfect-host bonus: slack after next item is minimal.
        let slack = pr - next_item_size as f64;
        if slack >= 0.0 && slack <= 4.0 {
            score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Aggressive dead-space elimination below fleet mean.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
    }

    // Early-stream consolidation: keep post residuals above fleet mean.
    if bin_residual != bin_capacity && post_residual > 0
        && open_bins_count >= 2 && open_bins_count <= 6
        && remaining_frac > 0.6 && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // MUTATION: two-step closure — if after placing the next item the
        // leftover can be closed by the fleet mean, deepen the reward.
        if open_bins_count >= 2 && mean_residual >= 1.0 && after_next > 0 {
            let an = after_next as f64;
            if (an + mean_residual - cap).abs() <= 4.0 {
                score -= 9.0 * (1.0 - (an + mean_residual - cap).abs() / 5.0) * (0.4 + remaining_frac);
            }
            if an >= mean_residual && (an - mean_residual).abs() <= 3.0 {
                score -= 5.0 * (1.0 - (an - mean_residual).abs() / 4.0) * remaining_frac;
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin when the new bin's own post residual would
            // itself be dead space (too small for the next item and below the
            // fleet mean's pairing reach) — the fresh bin would immediately
            // become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // A fresh bin is more acceptable when the item placed leaves
            // a post residual that is an exact multiple of the next item —
            // the new bin can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // MUTATION: fresh-bin post-residual quality gate — prefer opening
            // a bin whose leftover is large enough to host future items
            // (>= fleet mean), penalize thin leftovers harder mid-stream.
            if post_residual > 0 && mean_residual >= 1.0 {
                let pr = post_residual as f64;
                if pr < mean_residual {
                    score += 18.0 * (1.0 - pr / mean_residual) * (0.4 + remaining_frac);
                } else if (pr - mean_residual).abs() <= 4.0 {
                    score -= 12.0 * (1.0 - (pr - mean_residual).abs() / 5.0) * remaining_frac;
                }
            }
            // MUTATION: allow fresh bins late in the stream when open bins
            // are nearly full — squeezing into a nearly-closed bin strands
            // nothing, but a wasted near-full residual is worse.
            if remaining_frac < 0.35 && fit_ratio < 0.6 && open_bins_count > 2 {
                score -= 20.0 * (1.0 - fit_ratio);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination — for open bins, a post residual
    // that is smaller than the fleet mean's smallest useful payload is nearly
    // unrecoverable. Scale the penalty with how far below the mean it sits,
    // but only mid-stream where recovery still matters.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        // Reward leaving a residual that is itself a "perfect host" — large
        // enough to fit the next item with minimal slack.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Penalize open-bin placements that strand a residual just below a
    // common small-item size band (1..=10) when no small items are expected —
    // inferred from the next item being large.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus — prefer placements whose post residual can
    // absorb the next item AND whose remaining slack matches the fleet mean
    // residual closely, so the next-next placement can also close a bin.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation — when few bins are open and the stream
    // is young, mildly prefer bins whose post residual stays above the fleet
    // mean so future medium items still have hosts; below-mean leftovers
    // early on are the primary source of dead space.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // MUTATION: triple-lookahead — reward placements where the post residual
    // can host the next item AND the resulting leftover is itself a multiple
    // of the next item (chain of exact closures), scaled by stream position.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= 2 * next_item_size
        && post_residual % next_item_size == 0
        && remaining_frac > 0.3
    {
        score -= 6.0 * (0.4 + remaining_frac);
    }

    // MUTATION: penalize open bins left with residuals in the "orphan band"
    // just above the fleet mean that no plausible item (next or mean-sized)
    // can close exactly — a persistent source of dead space.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && mean_residual >= 1.0
        && next_item_size > 0
    {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if pr > nx && pr < nx + mean_residual && (pr - nx) > 2.0 {
            score += 5.0 * (1.0 - (pr - nx) / mean_residual.max(1.0)) * remaining_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened toward 1.0.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: after-next residual that exactly equals a plausible small-item
        // size (the most common sizes in unknown streams) is highly likely to
        // be closed by a future item — reward it mid-stream.
        if after_next >= 1 && after_next <= 30 && open_bins_count >= 2 && remaining_frac > 0.3 {
            let small_like = 1.0 - ((after_next as f64 - 8.0).abs() / 22.0);
            if small_like > 0.0 {
                score -= 5.0 * small_like * remaining_frac;
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin when the new bin's own post residual would
            // itself be dead space.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin closable in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // NEW: when the fleet's mean residual is large (bins are mostly
            // empty), opening a fresh bin is cheap and keeps residuals
            // homogeneous — damp the fresh-bin penalty.
            if mean_residual > 0.5 * cap {
                score -= 90.0 * ((mean_residual - 0.5 * cap) / (0.5 * cap)).min(1.0);
            }
            // NEW: refuse a fresh bin if the current item is small enough
            // that the fleet mean residual could host it — avoid fragmenting.
            if open_bins_count >= 2 && (item_size as f64) <= mean_residual * 0.9 {
                score += 35.0 * (1.0 - item_size as f64 / mean_residual.max(1.0)) * remaining_frac.max(0.3);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // NEW: penalize open-bin placements that strand a residual just below a
    // common small-item size band (1..=10) when no small items are expected.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // NEW: three-step lookahead — if after placing the item and the next item
    // the residual still cannot host a third placement of comparable size,
    // the bin risks triple-stranding. Penalize proportionally.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 3
        && remaining_frac > 0.25
    {
        let after_next = (post_residual - next_item_size) as f64;
        let probe = (next_item_size as f64).max(1.0) * 0.8;
        if after_next > 0.0 && after_next < probe && after_next + mean_residual < probe {
            score += 9.0 * (1.0 - after_next / probe) * remaining_frac;
        }
    }

    // NEW: endgame squeeze — near the end of the stream, every unit of
    // residual matters more; reward bins that keep large residuals usable
    // and punish small leftover fragments harder.
    if remaining_frac < 0.1 && bin_residual != bin_capacity && post_residual > 0 {
        if post_residual as f64 >= item_size as f64 {
            score -= 10.0 * (1.0 - remaining_frac * 10.0).max(0.0);
        } else {
            score += 12.0 * (1.0 - remaining_frac * 10.0).max(0.0);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if open_bins_count >= 3 && after_next > 0 {
            let pairable = (after_next as f64 + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 6.0 * (1.0 - pairable / (0.1 * cap)) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && item_size > 0 && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        if bin_residual != bin_capacity && mean_residual < next_item_size as f64 {
            score += 8.0 * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // MUTATION: reward residuals that exactly complement the fleet mean into a
    // full bin — actively closes bins by pairing leftovers.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // MUTATION: penalize near-miss leftovers — almost hostable by the fleet
    // mean but not quite, the most wasteful dead space.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        let target = next_item_size as f64;
        if pr < target && pr + mean_residual >= target - 6.0 {
            let near_miss = 1.0 - ((target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    if open_bins_count > 4 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0 && pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score -= 6.0 * remaining_frac;
        }
    }

    // MUTATION: chain-closure bonus — prefer placements whose post residual
    // can absorb the next item AND whose remaining slack matches the fleet
    // mean closely, so the next-next placement can also close a bin.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // MUTATION: aggressive dead-space elimination — a post residual below the
    // fleet mean's smallest useful payload is nearly unrecoverable mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // MUTATION: early-stream consolidation — keep residuals above the fleet
    // mean while few bins are open so future medium items still have hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // MUTATION: a fresh bin is only justified if its post-residual
            // pairs well with the tight fleet mean; otherwise squeeze in.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // MUTATION: late-stream sprawl control — a fresh bin late must be
            // nearly filled by this item, otherwise squeeze into the fleet.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // MUTATION: refuse a fresh bin whose own post residual would be
            // dead space — too small for the next item and beyond the fleet
            // mean's pairing reach; the new bin would immediately dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // MUTATION: prefer a fresh bin whose post residual pairs with the
            // fleet mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // MUTATION: fresh bin whose post residual is an exact multiple of
            // the next item can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let cap = bin_capacity as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Perfect fits.
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }

    // Dead-space penalty for tiny unusable gaps.
    if post_residual > 0 && post_residual <= 10 && bin_residual != bin_capacity {
        score += 40.0 * (1.0 + (10 - post_residual) as f64);
        score += 6.0 * remaining_frac;
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if fitting_bins_count >= 2 && (after_next as f64) < 0.2 * cap {
            score -= 8.0 * (1.0 - after_next as f64 / (0.2 * cap));
        }
        if next_item_size <= 20 {
            let chain_cap = 3 * next_item_size;
            if post_residual <= chain_cap {
                let tightness = 1.0 - after_next as f64 / (chain_cap - next_item_size) as f64;
                score -= 10.0 * tightness * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
            score -= 22.0;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
            let k = post_residual / next_item_size;
            if k * next_item_size <= bin_capacity {
                score -= 6.0 * (k.min(5) as f64 - 2.0);
            }
        }
        if post_residual < 2 * next_item_size {
            let frac = after_next as f64 / next_item_size as f64;
            if frac > 0.6 {
                score += 9.0 * frac;
            }
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Chain-closure bonus: post slack matching fleet mean promises closure.
        if open_bins_count >= 2 && mean_residual >= 1.0 {
            let an = after_next as f64;
            let closeness = (an - mean_residual).abs();
            if closeness <= 5.0 && an >= 1.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        // Dead-zone width guard.
        let band = after_next;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
        if next_item_size as f64 > mean_residual.max(1.0) * 1.6 && fitting_bins_count >= 2 {
            score += 8.0;
        }
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0
                && mean_residual >= next_item_size as f64
            {
                score += 20.0;
            }
            // Fresh bin whose post residual pairs with the fleet mean into a near-full bin.
            if open_bins_count >= 2 && mean_residual >= 1.0 && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin chainable in consecutive steps.
            if next_item_size > 0 && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Refuse fresh bin that would immediately become a dead-end.
            if open_bins_count > 2 && next_item_size > 0 && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Fleet mean can host item + half of next: keep packing into fleet.
            if open_bins_count > 2
                && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5
                && fit_ratio < 0.85
            {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    // Dead-zone accounting with fleet-absorbability weighting.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if post_residual as f64 > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Sub-mean slack penalty.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Dead-zone depth refinement.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
            // Two-step dead space: deficit beyond fleet mean pairing reach.
            if pr + mean_residual < ns {
                let deficit = ns - pr - mean_residual;
                score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
            }
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
        // Perfect-host bonus: minimal slack after next item.
        if bin_residual != bin_capacity {
            let slack = pr - next_item_size as f64;
            if slack >= 0.0 && slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Exact complement into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Early-stream consolidation: avoid below-mean leftovers while young.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Perfect closure.
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }

    // Dead-space penalty for tiny slivers.
    if post_residual > 0 && post_residual <= 10 && bin_residual != bin_capacity {
        let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
        let w = if fleet_absorb { 0.45 } else { 1.0 };
        score += w * 40.0 * (1.0 + (10 - post_residual) as f64);
        score += 6.0 * remaining_frac;
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain quality.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if fitting_bins_count >= 2 && (after_next as f64) < 0.2 * cap {
            score -= 8.0 * (1.0 - after_next as f64 / (0.2 * cap));
        }
        if next_item_size <= 20 {
            let chain_cap = 3 * next_item_size;
            if post_residual <= chain_cap {
                let tightness = 1.0 - after_next as f64 / (chain_cap - next_item_size) as f64;
                score -= 10.0 * tightness * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
            score -= 22.0;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
            let k = post_residual / next_item_size;
            if k * next_item_size <= bin_capacity {
                score -= 6.0 * (k.min(5) as f64 - 2.0);
            }
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        // Chain-closure bonus: slack after next matches fleet mean closely.
        if open_bins_count >= 2 && mean_residual >= 1.0 {
            let an = after_next as f64;
            let closeness = (an - mean_residual).abs();
            if closeness <= 5.0 && an >= 1.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
        if post_residual < 2 * next_item_size {
            let frac = after_next as f64 / next_item_size as f64;
            if frac > 0.6 {
                score += 9.0 * frac;
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
        if next_item_size as f64 > mean_residual.max(1.0) * 1.6 && fitting_bins_count >= 2 {
            score += 8.0;
        }
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0
                && mean_residual >= next_item_size as f64
            {
                score += 20.0;
            }
            // Fresh bin whose post residual is an exact small multiple of the
            // next item promises consecutive closure.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh bin whose residual complements the fleet mean into a full bin.
            if open_bins_count >= 2 && mean_residual >= 1.0 && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Refuse a fresh bin that would immediately become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    // Dead-zone accounting with fleet-absorb exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if post_residual as f64 > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let pairable_target = if next_item_size > 0 { next_item_size as f64 } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
