        }
    }

    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Penalize near-miss leftovers — almost hostable by the fleet mean.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        let target = next_item_size as f64;
        if pr < target && pr + mean_residual >= target - 6.0 {
            let near_miss = 1.0 - ((target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    if open_bins_count > 4 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0 && pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score -= 6.0 * remaining_frac;
        }
    }

    // MUTATION (from best): chain-closure bonus — prefer placements whose post
    // residual can absorb the next item AND whose remaining slack matches the
    // fleet mean residual closely, so the next-next placement can close a bin.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // MUTATION (from best): aggressive dead-space elimination — a post residual
    // below the fleet mean is nearly unrecoverable mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // MUTATION (from best): penalize stranded residuals just below the
    // small-item band when the next item is large.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // MUTATION (from best): early-stream consolidation — keep post residuals
    // above the fleet mean while few bins are open.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // MUTATION (from best): refuse a fresh bin whose post residual is
            // itself dead space — too small for the next item and below the
            // fleet mean's pairing reach.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // MUTATION (from best): prefer a fresh bin whose post residual
            // pairs with the fleet mean into a near-full bin.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // MUTATION (from best): fresh bin more acceptable when its post
            // residual is an exact multiple of the next item.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let cap = bin_capacity as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Sharpened snugness gradient across the whole fit range.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }

    // Dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual <= 10 && bin_residual != bin_capacity {
        score += 40.0 * (1.0 + (10 - post_residual) as f64);
        score += 6.0 * remaining_frac;
    }

    // Perfect 2-step match: leave exactly the next item's size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain quality and sliver shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        // Multiplicity-aware consolidation: mild quadratic shaping of usable slack.
        if fitting_bins_count >= 2 && (after_next as f64) < 0.2 * cap {
            score -= 8.0 * (1.0 - after_next as f64 / (0.2 * cap));
        }
        // Small-item stream anticipation: tight chains of tiny items.
        if next_item_size <= 20 {
            let chain_cap = 3 * next_item_size;
            if post_residual <= chain_cap {
                let tightness = 1.0 - after_next as f64 / (chain_cap - next_item_size) as f64;
                score -= 10.0 * tightness * (0.5 + remaining_frac);
            }
        }
        // Exact double-fill trap.
        if post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
            score -= 22.0;
        }
        // Exact k-chain lookahead: divisible residue predicts multi-item chains.
        if post_residual >= 3 * next_item_size && post_residual % next_item_size == 0 {
            let k = post_residual / next_item_size;
            if k * next_item_size <= bin_capacity {
                score -= 6.0 * (k.min(5) as f64 - 2.0);
            }
        }
        // Avoid stranding medium residue when a near-exact alternative exists.
        if post_residual < 2 * next_item_size {
            let frac = after_next as f64 / next_item_size as f64;
            if frac > 0.6 {
                score += 9.0 * frac;
            }
        }
        // Two-chain packing: reward room for next item plus a second copy.
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Dead-zone width guard: band just above the next item strands.
        let band = after_next;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
        // MUTATION: chain-closure bonus — prefer placements whose post residual
        // can absorb the next item AND whose remaining slack matches the fleet
        // mean residual closely, so the next-next placement can also close a bin.
        if bin_residual != bin_capacity
            && open_bins_count >= 2
            && mean_residual >= 1.0
            && after_next >= 1
        {
            let closeness = ((after_next as f64) - mean_residual).abs();
            if closeness <= 5.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
        // MUTATION: perfect-host reward — leaving a residual that fits the next
        // item with minimal slack is nearly a guaranteed closure.
        if bin_residual != bin_capacity && open_bins_count >= 3 {
            let slack = after_next as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        // Penalize dead space that cannot host the next item.
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        // Quadratic dead-zone depth coupling with remaining stream.
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
        // Split-fit insurance: next item likely needs a fresh home anyway.
        if next_item_size as f64 > mean_residual.max(1.0) * 1.6 && fitting_bins_count >= 2 {
            score += 8.0;
        }
        // MUTATION: dead-space recoverability via fleet composition — a residual
        // below the next item is less deadly if the fleet mean can pair it up.
        if bin_residual != bin_capacity && post_residual > 0 {
            let pr = post_residual as f64;
            let pair_ok = mean_residual >= 1.0 && pr + mean_residual >= next_item_size as f64;
            if !pair_ok && remaining_frac > 0.2 {
                let deficit = (next_item_size as f64 - pr).max(1.0);
                score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
            }
        }
    }

    // Harmonic pairing: a same-size item could follow.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation pressure toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0
                && item_size as f64 > 0.5 * cap
                && mean_residual < next_item_size as f64 + 4.0
            {
                score -= 35.0;
            }
            // Stranding justification: deep dead zone for the next item.
            if post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            // Fresh-bin appeal when fleet is stranded and fit is mediocre.
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            // Fleet-stranded fresh-bin discount scaled by next-item shortfall.
            if next_item_size > 0
                && mean_residual < next_item_size as f64
                && fit_ratio < 0.9
                && remaining_frac > 0.35
            {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            // Residual-value conservation: a fresh bin is cheap when the fleet
            // has plenty of mid-size residue left to host the next item.
            if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0
                && mean_residual >= next_item_size as f64
            {
                score += 20.0;
            }
            // MUTATION: refuse a fresh bin whose own post residual would itself
            // be dead space — the fresh bin would immediately become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // MUTATION: prefer a fresh bin whose post residual pairs with the
            // fleet mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // MUTATION: a fresh bin is more acceptable when its post residual is
            // an exact multiple of the next item — consecutive closure possible.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // MUTATION: late-stream — strongly refuse fresh bins when closing out.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    // Dead-zone accounting: residue in the dead zone scaled by depth and sink.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if post_residual as f64 > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            // MUTATION: exempt gaps the fleet mean can absorb — they remain
            // recoverable elsewhere, so weight them down.
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Global residual balancing.
    if open_bins_count >= 3 && bin_residual != bin_capacity {
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Sub-mean slack penalty: slack below mean residual is likely to strand.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Dead-zone depth refinement: residue reachable by the next item is much
    // less dead than residue below it; scale the gap quadratically.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    // Residual-value conservation: mid-size usable residue is valuable while
    // the stream is long.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity: keep pairable leftovers in the fleet.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // MUTATION: reward residuals that exactly complement the fleet mean into a
    // full bin, regardless of next-item relation.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // MUTATION: aggressive dead-space elimination — a post residual below the
    // fleet mean's smallest useful payload is nearly unrecoverable mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
    }

    // MUTATION: early-stream consolidation — below-mean leftovers early on are
    // the primary source of dead space; mildly penalize them.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Late-stream tightening: close bins hard near the end.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if open_bins_count >= 3 && after_next > 0 {
            let pairable = (after_next as f64 + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 6.0 * (1.0 - pairable / (0.1 * cap)) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && item_size > 0 && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        if bin_residual != bin_capacity && mean_residual < next_item_size as f64 {
            score += 8.0 * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // MUTATION: chain-closure bonus — post residual can host next item AND the
    // leftover after it matches the fleet mean closely, enabling a second closure.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // MUTATION: aggressive dead-space elimination — below-mean leftovers are
    // nearly unrecoverable; penalize quadratically mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // MUTATION: early-stream consolidation — keep post residuals above the
    // fleet mean while the stream is young so medium items retain hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    if open_bins_count > 4 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0 && pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score -= 6.0 * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // MUTATION: refuse a fresh bin whose own post residual would be a
            // dead-end (too small for next item and beyond the mean's pairing reach).
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // MUTATION: prefer a fresh bin whose post residual pairs with the
            // fleet mean into a near-full bin — promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // MUTATION: fresh bin acceptable if its post residual is an exact
            // multiple of the next item — consecutive closures possible.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // REFINED: after placing the next item, if the leftover could be
        // closed by the fleet mean, reward it — this tightens the two-step
        // lookahead toward actual bin closure rather than just fitting.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin when the new bin's own post residual would
            // itself be dead space (too small for the next item and below the
            // fleet mean's pairing reach) — the fresh bin would immediately
            // become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // A fresh bin is more acceptable when the item placed leaves
            // a post residual that is an exact multiple of the next item —
            // the new bin can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // NEW: fresh-bin promise check — a new bin is only worth opening
            // mid-stream if its post residual is large enough to remain a
            // viable host for typical (mean-scale) future items. A fresh bin
            // whose leftover is below the fleet mean's reach is a wasted
            // capacity unit; penalize proportionally to how unreachable it is.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // NEW: reward opening a fresh bin that closes the current item
            // exactly (post_residual == 0) when other open bins would strand
            // dead space — perfect closure justifies the extra bin.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination — for open bins, a post residual
    // that is smaller than the fleet mean's smallest useful payload is nearly
    // unrecoverable. Scale the penalty with how far below the mean it sits,
    // but only mid-stream where recovery still matters.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        // Reward leaving a residual that is itself a "perfect host" — large
        // enough to fit the next item with minimal slack.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // NEW: penalize open-bin placements that strand a residual just below a
    // common small-item size band (1..=10) when no small items are expected —
    // inferred from the next item being large.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // NEW: chain-closure bonus — prefer placements whose post residual can
    // absorb the next item AND whose remaining slack matches the fleet mean
    // residual closely, so the next-next placement can also close a bin.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // NEW: early-stream consolidation — when few bins are open and the stream
    // is young, mildly prefer bins whose post residual stays above the fleet
    // mean so future medium items still have hosts; below-mean leftovers
    // early on are the primary source of dead space.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // NEW: exact-complement sweep — when the post residual is within a small
    // tolerance of what ANY plausible future payload needs to close the bin,
    // treat it as nearly closed and reward it proportionally to the tolerance
    // and to how many bins are competing (scarce hosts matter more).
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        // Post residual equals a multiple of the next item minus a tiny
        // remainder: the bin can be closed by a short run of next-size items.
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // REFINED: after placing the next item, if the leftover could be
        // closed by the fleet mean, reward it — this tightens the two-step
        // lookahead toward actual bin closure rather than just fitting.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5
                && fit_ratio < 0.85
            {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin when the new bin's own post residual would
            // itself be dead space (too small for the next item and below the
            // fleet mean's pairing reach) — the fresh bin would immediately
            // become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // A fresh bin is more acceptable when the item placed leaves
            // a post residual that is an exact multiple of the next item —
            // the new bin can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise check — a new bin is only worth opening
            // mid-stream if its post residual is large enough to remain a
            // viable host for typical (mean-scale) future items.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Reward opening a fresh bin that closes the current item
            // exactly (post_residual == 0) when other open bins would strand
            // dead space — perfect closure justifies the extra bin.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // NEW: fresh-bin viability horizon — a new bin's post residual
            // must be able to host the next item with tight slack; if it
            // leaves a wide-but-unusable gap (too big for small items but
            // below the next item's size), penalize as an immediate dead end.
            if open_bins_count > 1
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (next_item_size - post_residual) <= 18
                && mean_residual < post_residual as f64
            {
                score -= 16.0 * (1.0 - (next_item_size - post_residual) as f64 / 19.0) * remaining_frac;
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination — for open bins, a post residual
    // that is smaller than the fleet mean's smallest useful payload is nearly
    // unrecoverable. Scale the penalty with how far below the mean it sits,
    // but only mid-stream where recovery still matters.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        // Reward leaving a residual that is itself a "perfect host" — large
        // enough to fit the next item with minimal slack.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Penalize open-bin placements that strand a residual just below a
    // common small-item size band (1..=10) when no small items are expected —
    // inferred from the next item being large.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus — prefer placements whose post residual can
    // absorb the next item AND whose remaining slack matches the fleet mean
    // residual closely, so the next-next placement can also close a bin.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation — when few bins are open and the stream
    // is young, mildly prefer bins whose post residual stays above the fleet
    // mean so future medium items still have hosts; below-mean leftovers
    // early on are the primary source of dead space.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Exact-complement sweep — when the post residual is within a small
    // tolerance of what ANY plausible future payload needs to close the bin,
    // treat it as nearly closed and reward it proportionally to the tolerance
    // and to how many bins are competing (scarce hosts matter more).
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // NEW MUTATION: residual-band targeting — mid-stream, prefer placements
    // whose post residual lands in the "high-value host band" (just above the
    // next item size, tight slack) when there are many competing bins; this
    // sharpens host selection and reduces dead space variance.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual > next_item_size
        && open_bins_count >= 4
        && remaining_frac > 0.3
    {
        let tight_slack = (post_residual - next_item_size) as f64;
        if tight_slack <= 10.0 {
            score -= 6.0 * (1.0 - tight_slack / 11.0) * remaining_frac
                * (fitting_bins_count.min(6) as f64 / 6.0);
        }
    }

    // NEW MUTATION: near-closure escalation — when a placement brings the
    // post residual within the reach of a single typical (mean) item, treat
    // it as one step from closure and reward it strongly, scaled by stream
    // progress; this converts marginal fits into completed bins.
    if bin_residual != bin_capacity
        && post_residual > 0
        && mean_residual >= 1.0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let reach = pr - mean_residual;
        if reach > 0.0 && reach <= 6.0 {
            score -= 5.0 * (1.0 - reach / 7.0) * (0.4 + remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if open_bins_count >= 3 && after_next > 0 {
            let pairable = (after_next as f64 + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 6.0 * (1.0 - pairable / (0.1 * cap)) * (0.4 + remaining_frac);
            }
        }
        // MUTATION: after-next closable by fleet mean — tighten toward closure.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // MUTATION: chain-closure bonus — after_next close to fleet mean means
        // the next-next placement can also close a bin.
        if open_bins_count >= 2 && mean_residual >= 1.0 && after_next >= 1 {
            let closeness = (after_next as f64 - mean_residual).abs();
            if closeness <= 5.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && item_size > 0 && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        if bin_residual != bin_capacity && mean_residual < next_item_size as f64 {
            score += 8.0 * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // MUTATION: near-miss leftovers — almost hostable by the fleet mean but
    // not quite, the most wasteful dead space.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        let target = next_item_size as f64;
        if pr < target && pr + mean_residual >= target - 6.0 {
            let near_miss = 1.0 - ((target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // MUTATION: below-mean dead space — post residual smaller than the fleet
    // mean's smallest useful payload is nearly unrecoverable mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // MUTATION: exact-complement sweep — post residual is a near-multiple of
    // the next item, closable by a short run of next-size items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // MUTATION: strand small residuals when only large items are expected.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    if open_bins_count > 4 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0 && pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score -= 6.0 * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Fresh bin only justified if its post residual pairs well with the
            // tight fleet mean; otherwise squeeze in.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream sprawl control.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // Refuse a fresh bin whose own post residual would be dead space.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet mean.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin closable by a run of next-size items.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise check: post residual must remain a viable host
            // for mean-scale future items.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Perfect closure justifies the extra bin.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // MUTATION: exact triple-closure — if after the next item the leftover
        // equals the next item again, the bin closes in exactly three steps.
        if after_next == next_item_size && next_item_size > 0 {
            score -= 16.0 * (0.5 + remaining_frac);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // MUTATION: fresh-bin viability — only open a new bin when the
            // fresh post residual can host the next item exactly; if the
            // fresh leftover is a stranded sliver, block the open hard.
            if next_item_size > 0
                && post_residual > 0
                && post_residual < next_item_size
                && open_bins_count > 1
            {
                score += 40.0 * remaining_frac;
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // MUTATION: endgame sweep — near the stream's end, any residual that can
    // still hold the next item is precious; reward it progressively as the
    // stream closes, and penalize leftover slivers that will never be filled.
    if remaining_frac < 0.3 && bin_residual != bin_capacity && next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 14.0 * (0.3 - remaining_frac) / 0.3 * (1.0 - waste_ratio);
        } else {
            score += 10.0 * (0.3 - remaining_frac) / 0.3;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Closable-after-next: leftover after placing the next item pairs
        // with the fleet mean into a near-full bin — two-step closure.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Exact-fit anticipation.
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Fresh-bin dead-end check.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Fresh-bin closure promise.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh-bin divisible residue chain.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin below-mean reach penalty.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Perfect closure justifies a fresh bin when others strand space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Divisible residue chains into zero-waste fills.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Exact-complement sweep with the fleet mean.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination + perfect-host reward.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Small-crumbs strand risk when a large item follows.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus: post residual after next item matches fleet mean.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation: keep leftovers above mean reach.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Exact-complement sweep: residual near a run of next-size items.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;
