    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let target = next_item_size as f64;
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= target;
        if pr < target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < target && mean_residual >= 1.0 && pr + mean_residual >= target - 6.0 {
            let near_miss = 1.0 - ((target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Fresh bin that immediately becomes a dead-end is pure waste.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Reward a fresh bin whose leftover pairs with the fleet mean into a full bin.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin closable in consecutive steps via divisible leftover.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise check: leftover must remain a viable host for
            // mean-scale future items, otherwise the capacity unit is wasted.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Perfect closure justifies an extra bin when other fits strand space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Aggressive dead-space elimination: leftover below the fleet mean's
    // smallest useful payload is nearly unrecoverable mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Early-stream consolidation: keep leftovers above the fleet mean while
    // the stream is young so medium items still have hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Small crumbs stranded when only large items are expected.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step closure: leftover after next item pairs with fleet mean into a full bin.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Chain-closure bonus: after-next slack matches the fleet mean residual
        // so the following placement can also close a bin.
        if open_bins_count >= 2 && mean_residual >= 1.0 {
            let an = after_next as f64;
            let closeness = (an - mean_residual).abs();
            if closeness <= 5.0 && an >= 1.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
        // Post residual nearly a whole multiple of the next item: closable by
        // a short run of next-size items.
        if open_bins_count >= 2 {
            let pr = post_residual as f64;
            let next = next_item_size as f64;
            if pr > next {
                let k = (pr / next).floor();
                let rem = pr - k * next;
                if rem <= 2.0 {
                    score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
                }
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= next;
        if pr < next && !pair_ok && remaining_frac > 0.2 {
            let deficit = (next - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < next && mean_residual >= 1.0 && pr + mean_residual >= next - 6.0 {
            let near_miss = 1.0 - ((next - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
        // Two-step lookahead on dead space.
        if pr + mean_residual < next {
            let deficit = next - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Exact-complement with fleet mean.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination: below-mean leftovers are near-unrecoverable.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Stranded small residue with a large next item.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Early-stream consolidation: keep post residuals above fleet mean.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Fresh bin that would immediately become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Fresh bin whose leftover pairs with fleet mean toward closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin with a divisible post residual chains into consecutive fills.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise check: leftover below fleet mean's reach is wasted capacity.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Perfect closure justifies an extra bin.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        // Two-chain packing: exactly two next-items fit with minimal slack.
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Exact double-fill trap.
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        // Small-item stream anticipation.
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        // Usable-slack shaping against fleet mean residual.
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        // k-chain lookahead — residue divisible by next item is a multi-slot future.
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // COMBINED: after placing the next item, a leftover closable by the
        // fleet mean signals near-closure — reward it.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
            // Chain-closure bonus: leftover matching the fleet mean residual
            // lets the next-next placement close a bin.
            let closeness = (after_next as f64 - mean_residual).abs();
            if closeness <= 5.0 && after_next as f64 >= 1.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Exact-fit anticipation: bin halved by current item invites a mirror fill.
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting in the dead zone, with fleet-absorbability exemption:
    // gaps the fleet mean residual can still host are recoverable, so penalize less.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            // Penalize opening a fresh bin when the fleet's mean residual
            // already exceeds the item — consolidation beats sprawl.
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            // Fleet-absorbability check — if mean residual alone can host
            // the item with room to spare, a fresh bin is pure sprawl.
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one (avoidable sprawl).
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Fresh-bin promise check — a new bin whose leftover is below the
            // fleet mean's reach is a wasted capacity unit; penalize deeply.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Reward a fresh bin that closes the item exactly when other open
            // bins would strand dead space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // A fresh bin is more acceptable when its post residual is an
            // exact multiple of the next item — consecutive-step closure.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard — bands of slack just above the next item tend to strand.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Prefer bins whose post residual is an exact multiple of small
    // upcoming crumbs — divisible residue chains into zero-waste fills.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // COMBINED: exact-complement sweep — a post residual that is a multiple
    // of the next item minus a tiny remainder can be closed by a short run
    // of next-size items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // COMBINED: aggressive dead-space elimination — post residual below the
    // fleet mean's smallest useful payload is nearly unrecoverable; scale
    // the penalty with depth, but reward residuals that tightly host the
    // next item.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // COMBINED: early-stream consolidation — keep post residuals above the
    // fleet mean early on so future medium items still have hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // COMBINED: penalize stranding a crumb (1..=10) when the next item is
    // large — no small items are coming to sweep it.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // COMBINED: reward residuals that exactly complement the fleet mean
    // into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // COMBINED: two-step dead-space lookahead — deficit below what the fleet
    // mean can pair into the next item's host.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Refined two-step lookahead toward actual bin closure.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin whose post residual would itself be dead space.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet mean.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin closable in consecutive steps by next-size items.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise check: leftover must stay reachable by mean-scale items.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Reward opening a fresh bin that closes the current item exactly.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // MUTATION: fresh-bin viability horizon — a new bin is only worth
            // opening mid-stream if its post residual can host at least the
            // next item OR pair with the fleet mean to near-closure. Otherwise
            // the fresh bin becomes an immediate dead unit; penalize by the
            // size of the stranded leftover relative to capacity.
            if open_bins_count > 1
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (cap - (post_residual as f64 + mean_residual)) > 8.0
                && remaining_frac > 0.15
            {
                let strand_frac = 1.0 - post_residual as f64 / next_item_size.max(1) as f64;
                score += 18.0 * strand_frac * (0.4 + remaining_frac);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination for open bins.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Penalize open-bin placements that strand a residual in the small band
    // (1..=10) when the next item is large.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Exact-complement sweep: post residual equals a multiple of the next
    // item minus a tiny remainder — closable by a short run of next-size items.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // MUTATION: two-step exact-closure sweep — prefer placements where the
    // post residual, after hosting the next item, lands within a tight
    // tolerance of the fleet mean so the following step closes the bin
    // exactly. This targets the residual dead-space directly.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
        && remaining_frac > 0.1
    {
        let after_next = post_residual - next_item_size;
        if after_next > 0 {
            let gap = (after_next as f64 - mean_residual).abs();
            if gap <= 2.0 {
                score -= 12.0 * (1.0 - gap / 3.0) * remaining_frac;
            }
        }
    }

    // MUTATION: mid-stream residual preservation — when many bins are open
    // and the stream is young, mildly penalize placements that drop a bin's
    // residual below the mean, since those leftovers become the dominant
    // source of end-of-stream waste.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count > 6
        && remaining_frac > 0.5
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.8 {
            score += 4.0 * (1.0 - pr / (mean_residual * 0.8).max(1.0)) * remaining_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step closure lookahead: after the next item lands, if the
        // leftover is closable by the fleet mean, reward it.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // REFINED: three-step lookahead — if after the next item the residual
        // can still host a mean-scale payload AND close against the fleet,
        // this bin promises a second closure; reward scaled by scarcity.
        if after_next > 0 && open_bins_count >= 3 && mean_residual >= 1.0
            && (after_next as f64) >= mean_residual
        {
            let second = after_next as f64 - mean_residual;
            if (second + mean_residual - cap).abs() <= 5.0 {
                score -= 6.0 * (1.0 - (second + mean_residual - cap).abs() / 6.0)
                    * (0.3 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin when the new bin's own post residual would
            // itself be dead space (too small for the next item and below the
            // fleet mean's pairing reach) — the fresh bin would immediately
            // become a dead-end.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // A fresh bin is more acceptable when the item placed leaves
            // a post residual that is an exact multiple of the next item —
            // the new bin can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise check — a new bin is only worth opening
            // mid-stream if its post residual is large enough to remain a
            // viable host for typical (mean-scale) future items.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Reward opening a fresh bin that closes the current item
            // exactly (post_residual == 0) when other open bins would strand
            // dead space — perfect closure justifies the extra bin.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // REFINED: fresh-bin viability floor — a new bin whose post
            // residual is below the next item size AND below the fleet mean
            // is a dead unit; escalate the penalty late in the stream where
            // recovery chances vanish.
            if open_bins_count > 1
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.3
            {
                score += 18.0 * remaining_frac;
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination — for open bins, a post residual
    // that is smaller than the fleet mean's smallest useful payload is nearly
    // unrecoverable. Scale the penalty with how far below the mean it sits,
    // but only mid-stream where recovery still matters.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        // Reward leaving a residual that is itself a "perfect host" — large
        // enough to fit the next item with minimal slack.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Penalize open-bin placements that strand a residual just below a
    // common small-item size band (1..=10) when no small items are expected —
    // inferred from the next item being large.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus — prefer placements whose post residual can
    // absorb the next item AND whose remaining slack matches the fleet mean
    // residual closely, so the next-next placement can also close a bin.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation — when few bins are open and the stream
    // is young, mildly prefer bins whose post residual stays above the fleet
    // mean so future medium items still have hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Exact-complement sweep — when the post residual is within a small
    // tolerance of what a run of next-size items needs to close the bin,
    // treat it as nearly closed and reward it proportionally.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // NEW: residual-band host matching — prefer open bins whose post residual
    // lands inside the "usable host" band (>= next item and >= fleet mean),
    // with a graded reward that sharpens when few fitting bins compete.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 1
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        let floor = next_item_size as f64;
        if pr >= mean_residual {
            let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
            let host_quality = 1.0 - ((pr - floor) / cap).min(1.0);
            score -= 5.0 * host_quality * scarcity * (0.4 + remaining_frac);
        }
    }

    // NEW: endgame exact-closure sweep — late in the stream, a placement that
    // closes a bin exactly (post_residual == 0) is worth far more than the
    // base bonus suggests, since remaining capacity is the binding constraint.
    if post_residual == 0 && bin_residual != bin_capacity && remaining_frac < 0.4 {
        score -= 20.0 * (0.4 - remaining_frac) * (2.5 - waste_ratio.max(0.0) * 2.0);
    }

    // NEW: mean-residual drift guard — when the fleet mean residual is small
    // (bins are nearly full), strongly avoid placements that leave residuals
    // below the mean, since those gaps will never be revisited.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 4
        && mean_residual >= 1.0
        && mean_residual < 0.1 * cap
        && (post_residual as f64) < mean_residual
    {
        let depth = 1.0 - post_residual as f64 / mean_residual;
        score += 10.0 * depth * (0.5 + remaining_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if open_bins_count >= 3 && after_next > 0 {
            let pairable = (after_next as f64 + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 6.0 * (1.0 - pairable / (0.1 * cap)) * (0.4 + remaining_frac);
            }
        }
        // MUTATION: two-step closure — after the next item lands, if the
        // leftover can be closed by the fleet mean, reward it.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // MUTATION: chain-closure — after_next matching the fleet mean
        // closely means the next-next placement can also close a bin.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closeness = (after_next as f64 - mean_residual).abs();
            if closeness <= 5.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && item_size > 0 && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        if bin_residual != bin_capacity && mean_residual < next_item_size as f64 {
            score += 8.0 * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // MUTATION: aggressive dead-space elimination — a post residual below the
    // fleet mean is nearly unrecoverable; penalize by depth, mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // MUTATION: exact-complement sweep — post residual is a multiple of the
    // next item minus a tiny remainder: closable by a short run of next items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // MUTATION: early-stream consolidation — keep residuals above the fleet
    // mean early so future medium items still have hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    if open_bins_count > 4 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0 && pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score -= 6.0 * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // MUTATION: fresh-bin dead-end check — refuse a fresh bin whose
            // post residual is unusable by the next item AND unreachable by
            // the fleet mean.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // MUTATION: prefer a fresh bin whose post residual pairs with the
            // fleet mean into a near-full bin — promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // MUTATION: fresh bin closable by a short run of next-size items.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // MUTATION: fresh-bin promise — its leftover must remain a viable
            // host for mean-scale future items.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // MUTATION: perfect closure via fresh bin when other bins strand
            // dead space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step closure: after_next pairs with the fleet mean into a
        // near-full bin — the strongest signal of eventual closure.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // MUTATION: after_next fully absorbable by the fleet mean alone —
        // the bin closes with one mean-sized item; reward scaled by scarcity
        // of fitting hosts.
        if after_next > 0
            && open_bins_count >= 2
            && mean_residual >= 1.0
            && (after_next as f64) <= mean_residual * 1.1
        {
            let depth = 1.0 - after_next as f64 / (mean_residual * 1.1);
            score -= 8.0 * depth * (0.6 + remaining_frac) * (1.0 / fitting_bins_count.max(1) as f64).sqrt();
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Refuse a fresh bin whose post residual would itself be dead space.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Prefer a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — it promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // A fresh bin whose post residual is an exact multiple of the
            // next item can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise check — a new bin is only worth opening
            // mid-stream if its post residual remains a viable host for
            // mean-scale future items.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Reward opening a fresh bin that closes the current item exactly
            // when other open bins would strand dead space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // MUTATION: fresh-bin viability band — reward a new bin whose
            // post residual sits in the "hostable" band (>= mean_residual and
            // >= next item), since such a bin stays recoverable; penalize
            // fresh bins whose leftover is just above the mean (hard to
            // close exactly) when many bins are already open.
            if open_bins_count > 2 && post_residual > 0 && mean_residual >= 1.0 {
                let pr = post_residual as f64;
                if pr >= mean_residual && pr >= next_item_size as f64 {
                    score -= 6.0 * (1.0 - remaining_frac);
                } else if pr > mean_residual && pr < next_item_size as f64 {
                    let overshoot = (pr - mean_residual) / pr.max(1.0);
                    score += 10.0 * overshoot * remaining_frac;
                }
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Penalize open-bin placements that strand a residual just below a
    // common small-item size band (1..=10) when no small items are expected.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Exact-complement sweep.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // MUTATION: late-stream exact-fit escalation — as the stream nears its
    // end, only near-perfect placements are worth taking; push marginal fits
    // toward bins whose post residual is small enough to be plausibly
    // closed by the remaining items.
    if remaining_frac < 0.35 && bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let urgency = 1.0 - remaining_frac / 0.35;
        if pr > 0.3 * cap {
            score += 14.0 * urgency * (pr / cap);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 2.0 {
                score -= 12.0 * urgency * (1.0 - slack / 3.0);
            }
        }
    }

    // MUTATION: residual-variance-aware consolidation — when open-bin
    // residuals are tightly clustered near the mean (low spread), prefer
    // placements that keep the cluster tight; a tight cluster means any
    // mean-sized item can close several bins, amplifying future closure
    // options.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 4
        && mean_residual >= 1.0
    {
        let dev = ((post_residual as f64 - mean_residual) / cap).abs();
        if dev < 0.08 {
            score -= 6.0 * (1.0 - dev / 0.08) * (0.4 + remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step closure: after-next residual pairs with fleet mean.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if open_bins_count >= 3 && after_next > 0 {
            let pairable = (after_next as f64 + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 6.0 * (1.0 - pairable / (0.1 * cap)) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && item_size > 0 && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        if bin_residual != bin_capacity && mean_residual < next_item_size as f64 {
            score += 8.0 * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Near-miss leftovers: almost hostable by fleet mean but not quite.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        let target = next_item_size as f64;
        if pr < target && pr + mean_residual >= target - 6.0 {
            let near_miss = 1.0 - ((target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // Aggressive dead-space elimination: below-mean leftovers mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Chain-closure bonus: after-next slack matches fleet mean.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Exact-complement sweep: post residual nearly closed by a run of next items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    if open_bins_count > 4 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > 0 && pr < next_item_size as f64 && mean_residual >= next_item_size as f64 {
            score -= 6.0 * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            // Fresh bin must pair its post residual with the fleet mean.
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            // Late-stream sprawl control.
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // Fresh bin whose post residual is dead space (below next item and
            // below fleet mean's pairing reach) is a wasted capacity unit.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Reward fresh bins whose post residual pairs with the fleet mean.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin closable by a run of next-size items.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin promise: leftover must stay reachable by fleet mean.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Perfect closure justifies the extra bin.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if open_bins_count >= 3 && after_next > 0 {
            let pairable = (after_next as f64 + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 6.0 * (1.0 - pairable / (0.1 * cap)) * (0.4 + remaining_frac);
            }
        }
        // MUTATION: chain-closure bonus — after the next item, if the leftover
        // matches the fleet mean, the next-next placement can close the bin.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closeness = ((after_next as f64) - mean_residual).abs();
            if closeness <= 5.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual < next_item_size {
        score += 14.0;
    }

    if post_residual > 0 && post_residual < 6 && bin_residual != bin_capacity {
        score += 6.0 * remaining_frac;
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && item_size > 0 && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        if bin_residual != bin_capacity && mean_residual < next_item_size as f64 {
            score += 8.0 * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 2 && next_item_size > 0 && post_residual >= next_item_size {
        let usable = (post_residual - next_item_size) as f64;
        if usable < 0.2 * cap {
            score -= 8.0 * (1.0 - usable / (0.2 * cap));
        }
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0 && post_residual == 2 * next_item_size && 2 * next_item_size <= bin_capacity {
        score -= 22.0;
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let ns = next_item_size as f64;
        if pr < ns {
            let dead = (ns - pr) / ns;
            score += 14.0 * dead * dead * (0.4 + remaining_frac);
        } else {
            let slack = pr - ns;
            score += slack * 0.05 * remaining_frac;
        }
    }

    if next_item_size > 0 && next_item_size <= 20 && post_residual >= next_item_size {
        let chain_cap = 3 * next_item_size;
        if post_residual <= chain_cap {
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / (chain_cap - next_item_size) as f64;
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // MUTATION: aggressive dead-space elimination — sub-mean leftovers are
    // nearly unrecoverable; penalize quadratically mid-stream.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // MUTATION: exact-complement sweep — post residual closable by a short
    // run of next-size items (multiple minus tiny remainder).
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if progress > 0.7 && fit_ratio < 0.9 {
                score += 25.0 * (0.9 - fit_ratio) * (progress - 0.7) * 10.0;
            }
            // MUTATION: fresh-bin promise check — a new bin whose post residual
            // is below the fleet mean's reach is wasted capacity.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // MUTATION: reward a fresh bin that pairs with the fleet mean into
            // a near-full bin — promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // MUTATION: fresh bin closable by consecutive next-size items.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // MUTATION: perfect closure justifies an extra bin when other
            // hosts would strand dead space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if fitting_bins_count >= 3 && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score += slack * 0.12;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step lookahead toward actual bin closure: after the next item
        // lands, if the leftover pairs with the fleet mean into a full bin,
        // reward it — this tightens residual fitting with closure anticipation.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Chain-closure bonus: post-residual slack matching the fleet mean
        // invites a next-next placement that closes the bin.
        if open_bins_count >= 2 && mean_residual >= 1.0 && after_next >= 1 {
            let closeness = (after_next as f64 - mean_residual).abs();
            if closeness <= 5.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= next;
        if pr < next && !pair_ok && remaining_frac > 0.2 {
            let deficit = (next - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < next && mean_residual >= 1.0 && pr + mean_residual >= next - 6.0 {
            let near_miss = 1.0 - ((next - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // Aggressive dead-space elimination: below-mean leftovers are nearly
    // unrecoverable mid-stream; reward near-tight hosts of the next item.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Reward residuals that complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Exact-complement sweep: residual closed by a short run of next-size items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            // Fresh-bin dead-end check: a new bin whose leftover can't host
            // the next item even with fleet-mean pairing is pure sprawl.
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            // Fresh-bin promise: post residual pairs with the fleet mean
            // into a near-full bin — future closure justifies the bin.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // Fresh bin closable in consecutive steps via next-size run.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin reachability: leftover below the fleet mean's reach
            // is a wasted capacity unit; penalize by unreachability depth.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Perfect closure justifies the extra bin.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Divisible residue chains into zero-waste fills.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Early-stream consolidation: below-mean leftovers early on cause dead space.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Small-crumb stranding when a large item is expected next.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step closure: after-next residual closable by fleet mean.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Chain-closure bonus: after-next slack matches fleet mean closely.
        if open_bins_count >= 2 && mean_residual >= 1.0 && after_next >= 1 {
            let closeness = (after_next as f64 - mean_residual).abs();
            if closeness <= 5.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
        // Near-multiple sweep: post residual closes with a short run of next-size items.
        if pr_closes_run(post_residual, next_item_size) {
            let k = post_residual / next_item_size;
            let rem = post_residual - k * next_item_size;
            score -= 10.0 * (1.0 - rem as f64 / 3.0) * (0.4 + remaining_frac) * (k.min(3) as f64 / 3.0);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Exact-fit anticipation.
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
        if next_item_size > 12 && remaining_frac > 0.15 {
            score += 6.0 * remaining_frac;
        }
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
        // Dead-space recoverability via fleet composition.
        let pr = post_residual as f64;
        let pairable_target = if next_item_size > 0 { next_item_size as f64 } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
        // Two-step dead-space deficit.
        if next_item_size > 0 && pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
        // Exact-complement reward.
        if post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let sum = pr + mean_residual;
            if (sum - cap).abs() <= 3.0 {
                score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
            }
        }
        // Below-mean leftovers mid-stream are dead-space seeds.
        if open_bins_count >= 3 && mean_residual >= 1.0 && pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Divisible residue chains into zero-waste fills.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Perfect-host reward: residual fits next item with minimal slack.
    if bin_residual != bin_capacity && open_bins_count >= 3 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    score
}

#[inline]
fn pr_closes_run(post_residual: u32, next_item_size: u32) -> bool {
    post_residual > next_item_size && next_item_size > 0 && post_residual % next_item_size <= 2
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Near-perfect fits rewarded strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorption exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            // Fresh-bin viability check: a leftover below the fleet mean's
            // reach is a wasted capacity unit mid-stream.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Reward a fresh bin that closes the current item exactly when
            // other open bins would strand dead space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // MUTATION: a fresh bin whose post residual can host BOTH the
            // next item and the fleet mean (triple-completion promise) is
            // a strong candidate — reward it proportionally to the slack.
            if open_bins_count >= 2
                && next_item_size > 0
                && mean_residual >= 1.0
                && post_residual >= next_item_size
            {
                let triple_slack = post_residual as f64 - next_item_size as f64 - mean_residual;
                if triple_slack >= -4.0 && triple_slack <= 6.0 {
                    score -= 14.0 * (1.0 - (triple_slack + 4.0).abs() / 10.0) * (0.4 + remaining_frac);
                }
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination for below-mean leftovers.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Penalize residuals stranded in the 1..=10 band when small items
    // are unlikely (next item is large).
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Chain-closure bonus: post residual absorbs next item AND remaining
    // slack matches the fleet mean, enabling a next-next closure.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    // Early-stream consolidation: keep leftovers above the fleet mean while
    // few bins are open so medium items still have hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Exact-complement sweep: post residual is a multiple of the next item
    // minus a tiny remainder — the bin closes via a short run of next items.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // MUTATION: residual-band matching — when several bins can host the item,
    // prefer the one whose post residual lands in the same "size class" as
    // the fleet mean residual (harmonized leftovers pack better downstream),
    // and mildly penalize leftovers that fall into the awkward 11..=20 band
    // when the fleet mean is far from it (few future items will fill it).
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        let band_gap = ((pr - mean_residual).abs() / cap).min(1.0);
        if fitting_bins_count >= 3 {
            score += 6.0 * band_gap * remaining_frac;
        }
        if pr >= 11.0 && pr <= 20.0 && (mean_residual - pr).abs() > 12.0 {
            score += 5.0 * (0.4 + remaining_frac);
        }
    }

    // MUTATION: two-item lookahead pair-fit — if the next item AND the item
    // after it (approximated by the fleet mean as a proxy) both fit into the
    // post residual, the bin is on a clean closure path; reward the nearness
    // of a perfect double-fill.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual > next_item_size
        && mean_residual >= 1.0
        && open_bins_count >= 2
    {
        let double_fill = post_residual as f64 - next_item_size as f64 - mean_residual;
        if double_fill >= 0.0 && double_fill <= 8.0 {
            score -= 8.0 * (1.0 - double_fill / 9.0) * (0.3 + remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step closure: after the next item, leftover closable by fleet mean.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Chain-closure bonus: leftover matches fleet mean so next-next can close.
        if open_bins_count >= 2 && mean_residual >= 1.0 {
            let an = after_next as f64;
            let closeness = (an - mean_residual).abs();
            if closeness <= 5.0 && an >= 1.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= next;
        if pr < next && !pair_ok && remaining_frac > 0.2 {
            let deficit = (next - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < next && mean_residual >= 1.0 && pr + mean_residual >= next - 6.0 {
            let near_miss = 1.0 - ((next - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Stranding medium residue near-exact alternative.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Divisible residue chains.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Exact-complement sweep.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination with perfect-host reward.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // Small-crumbs stranded when large items expected.
    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    // Early-stream consolidation.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    // Exact-complement sweep: multiple of next item minus tiny remainder.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        // Two-chain packing: exactly two next-items fit with minimal slack.
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        // Exact double-fill trap.
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        // Small-item stream anticipation.
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        // Usable-slack shaping against fleet mean residual.
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        // k-chain lookahead — residue divisible by next item is a multi-slot future.
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: closure-oriented lookahead — reward placements whose post-next
        // leftover can be closed by the fleet mean residual (pairing into a
        // near-full bin), steering the two-step chain toward actual closure.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // NEW: chain-closure bonus — after-next slack matching the fleet mean
        // means the next-next placement can also close a bin cleanly.
        if open_bins_count >= 2 && mean_residual >= 1.0 {
            let closeness = ((after_next as f64) - mean_residual).abs();
            if closeness <= 5.0 && after_next >= 1 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    // Exact-fit anticipation: bin halved by current item invites a mirror fill.
    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs are prime targets for later small items.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting in the dead zone, with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // NEW: below-mean leftover penalty — an open-bin residual smaller than the
    // fleet mean's smallest useful payload is nearly unrecoverable dead space.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        // Reward leaving a residual that is a "perfect host" for the next item.
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // NEW: exact-complement sweep — post residual nearly a whole multiple of
    // the next item means the bin can be closed by a short run of next items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            // Penalize opening a fresh bin when the fleet's mean residual
            // already exceeds the item — consolidation beats sprawl.
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            // Fleet-absorbability check.
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            // Refuse a fresh bin when the fleet's best residual could host
            // both this item and the next one.
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // Fresh-bin promise check — a new bin whose leftover is below the
            // fleet mean's reach is a wasted capacity unit.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // Reward a fresh bin that closes the current item exactly when
            // other open bins would strand dead space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // Reward a fresh bin whose post residual pairs with the fleet
            // mean into a near-full bin — promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // A fresh bin whose post residual is a multiple of the next item
            // can be closed in consecutive steps.
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Divisible residue chains into zero-waste fills.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post_residual as f64;

    // Non-linear tightening: quadratic penalty shaping on post_residual
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Reward near-perfect fits, stronger as stream progresses (smooth coupling)
    let tightness = 1.0 - pr / bin_capacity as f64;
    score -= (0.5 + 2.5 * progress) * tightness.powi(3) * 20.0;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 20.0 * progress;
    }

    // Lookahead: penalize leaving a residual that exactly wastes the next item's fit
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.12 * gap;
        if post_residual >= next_item_size {
            score -= 4.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Discard lightly-used bins late when mean residual is large (consolidate)
    score += 0.05 * (bin_residual as f64 - mean_residual) * (1.0 + progress);

    // Mild preference to keep many open bins from proliferating: favor filling existing
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: penalize so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0 + 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly, sharpened at the top end.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Next item still fits after placement: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        score -= 50.0 + (after_next) as f64 * 0.35;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // REFINED: prefer post residuals that remain divisible by the next
        // item's size after the lookahead placement — guarantees a second
        // consecutive exact fit and drives dead space to zero in runs.
        if after_next > 0 && next_item_size > 1 && after_next % next_item_size == 0 {
            let k = (after_next / next_item_size).min(3);
            score -= 6.0 * k as f64 * (0.3 + remaining_frac);
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting: penalize unusable gaps, but exempt gaps that the
    // fleet mean residual can absorb (they remain recoverable elsewhere).
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = mean_residual >= post_residual as f64 && open_bins_count >= 2;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        let gap_frac = (next_item_size - post_residual) as f64 / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
    }

    // Dead-space recoverability via fleet composition.
    if bin_residual != bin_capacity && post_residual > 0 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        let pairable_target = if next > 0.0 { next } else { pr };
        let pair_ok = mean_residual >= 1.0 && (pr + mean_residual) >= pairable_target;
        if pr < pairable_target && !pair_ok && remaining_frac > 0.2 {
            let deficit = (pairable_target - pr).max(1.0);
            score += (3.0 + 9.0 * (deficit / cap).min(1.0)) * (0.4 + remaining_frac);
        }
        if pr < pairable_target && mean_residual >= 1.0 && pr + mean_residual >= pairable_target - 6.0 {
            let near_miss = 1.0 - ((pairable_target - pr - mean_residual).max(0.0) / 6.0);
            score += 4.0 * near_miss * remaining_frac;
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            if open_bins_count > 4
                && next_item_size > 0
                && mean_residual >= item_size as f64 * 1.3
                && mean_residual >= next_item_size as f64 * 1.1
                && remaining_frac > 0.3
            {
                score += 55.0 * (1.0 - remaining_frac) * 0.5 + 25.0;
            }
            if open_bins_count > 6 && progress < 0.4 && fit_ratio < 0.8 {
                score += 35.0 * (0.8 - fit_ratio) * 4.0;
            }
            if open_bins_count > 2
                && next_item_size > 0
                && mean_residual < 0.15 * cap
                && post_residual > 0
                && (post_residual as f64 + mean_residual) < next_item_size as f64
            {
                score += 30.0;
            }
            if remaining_frac < 0.25 && fit_ratio < 0.9 {
                score += 60.0 * (0.25 - remaining_frac) * 4.0 * (1.0 - fit_ratio);
            }
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            if next_item_size > 0
                && post_residual > 0
                && post_residual % next_item_size == 0
                && post_residual <= 3 * next_item_size
                && open_bins_count > 1
            {
                score -= 30.0 * (0.5 + remaining_frac);
            }
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // REFINED: a fresh bin whose post residual is an exact multiple of
            // the fleet mean residual promises repeated closure via typical
            // payloads — reward this compaction-friendly opening.
            if open_bins_count > 2
                && mean_residual >= 2.0
                && post_residual > 0
                && (post_residual as f64) % mean_residual < 1.0
                && remaining_frac > 0.3
            {
                score -= 14.0 * (0.4 + remaining_frac);
            }
            // REFINED: opening a fresh bin mid-stream when the fleet mean can
            // already absorb the current item is wasteful — penalize harder
            // as the stream progresses (early slack is cheap, late slack is not).
            if open_bins_count > 2 && mean_residual >= item_size as f64 && fit_ratio < 0.9 {
                score += 20.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
        }
    }

    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    if next_item_size > 0
        && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size
        && fitting_bins_count >= 2
    {
        score += 8.0;
    }

    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // Two-step lookahead on dead space.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > 0 {
        let pr = post_residual as f64;
        if pr < next_item_size as f64 && pr + mean_residual < next_item_size as f64 {
            let deficit = next_item_size as f64 - pr - mean_residual;
            score += 6.0 * (deficit / cap).min(1.0) * (0.5 + remaining_frac);
        }
    }

    // Reward residuals that exactly complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // Aggressive dead-space elimination.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    if bin_residual != bin_capacity
        && post_residual >= 1
        && post_residual <= 10
        && next_item_size > 12
        && remaining_frac > 0.15
    {
        score += 6.0 * remaining_frac;
    }

    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual >= next_item_size
        && open_bins_count >= 2
        && mean_residual >= 1.0
    {
        let after_next = (post_residual - next_item_size) as f64;
        let closeness = (after_next - mean_residual).abs();
        if closeness <= 5.0 && after_next >= 1.0 {
            score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
        }
    }

    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 2
    {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // NEW: residual variance control — mid-stream, prefer placements whose
    // post residual stays within one next-item width of the fleet mean, so
    // future payloads have predictable hosts; outliers (very large or very
    // small leftovers) create unpredictable dead space later.
    if bin_residual != bin_capacity
        && post_residual > 0
        && next_item_size > 0
        && open_bins_count >= 3
        && remaining_frac > 0.3
        && remaining_frac < 0.85
    {
        let pr = post_residual as f64;
        let upper = mean_residual + next_item_size as f64;
        if pr > upper {
            score += 4.0 * ((pr - upper) / cap).min(1.0) * remaining_frac;
        }
    }

    // NEW: late-stream tightening — near the end, bins that can still host
    // the next item exactly are worth disproportionately more than leaving
    // scattered medium residuals; sharpen the exact-host reward.
    if bin_residual != bin_capacity
        && next_item_size > 0
        && post_residual == next_item_size * 2
        && remaining_frac < 0.4
    {
        score -= 14.0 * (0.4 - remaining_frac);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 5 bands.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 5.0).floor() as i64; // 0..4 (0 = tightest fit)

    // Reward tight fits strongly (low class => low score).
    score -= (4 - class) as f64 * 6.0;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 15.0;
    }

    // Modulo arithmetic on post_residual: multiples of 5 and 10 pair well
    // with typical item sizes, keep them cheap; odd awkward residuals penalized.
    if post_residual % 10 == 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    } else {
        score += 2.0;
    }

    // Lookahead: if next item can exactly fill the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover after the next placement.
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
            if after_next == 0 {
                score -= 10.0;
            }
        } else {
            // next item won't fit here: residual becomes dead space; penalize
            // proportionally to how "wasted" it is, but small residuals are fine.
            score += (post_residual as f64 - next_item_size as f64).abs() * 0.05;
        }
    } else {
        // Last item: strongly prefer tightest possible fit.
        score -= 20.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no good fit exists. Base penalty for wasting a
    // fresh bin, scaled by how well the item would fill it.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        // Empty bin: score ~ residual minus fill incentive.
        score = bin_capacity as f64 - fill_ratio * 60.0;
        if fitting_bins_count == 0 {
            score -= 25.0; // no alternative: new bin is fine
        }
        if item_size >= 50 {
            score -= 10.0; // big items fine to start fresh
        }
        // If open bins are mostly full (low mean residual), new bin is natural.
        score -= (bin_capacity as f64 - mean_residual) * 0.05;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 8.0; // room for lookahead pairing in fresh bin
        }
    } else {
        // Slight global pressure: many open bins -> prefer consolidating.
        score += open_bins_count as f64 * 0.05;
        // Progress: late in stream, prefer tighter packing.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += frac * 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    let waste_ratio = post_residual as f64 / cap;
    let remaining_frac = (total_items.saturating_sub(step_index)) as f64 / total_items.max(1) as f64;

    // Snugness gradient.
    if fit_ratio > 0.85 {
        score -= 58.0 * fit_ratio;
    }
    if fitting_bins_count >= 2 && fit_ratio > 0.6 {
        score -= 8.0 * (fit_ratio - 0.6);
    }
    if fit_ratio > 0.97 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 70.0;
        if fitting_bins_count >= 2 {
            score -= 25.0;
        }
    }

    // Perfect 2-step match.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }

    // Two-step lookahead with chain shaping.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        let chain_ratio = next_item_size as f64 / post_residual.max(1) as f64;
        score -= 50.0 + 40.0 * chain_ratio + 0.35 * after_next.min(60) as f64;
        if after_next <= 3 {
            score -= 12.0;
        }
        if after_next > 0 && after_next < next_item_size / 2 {
            score += 7.0;
        }
        if after_next >= 2 * next_item_size {
            score -= 10.0;
        }
        if after_next >= next_item_size && after_next - next_item_size <= 4 {
            score -= 6.0;
        }
        if after_next >= 1 && after_next <= 12 {
            score -= 7.0;
        }
        if after_next >= 30 {
            score -= 6.0;
        }
        if fitting_bins_count >= 3 {
            score += after_next as f64 * 0.12;
        }
        if post_residual >= 2 * next_item_size && post_residual < 3 * next_item_size {
            let slack2 = post_residual - 2 * next_item_size;
            if slack2 <= 4 {
                score -= 11.0 * (1.0 - slack2 as f64 / 5.0) * (0.5 + remaining_frac);
            }
        }
        if post_residual == 2 * next_item_size {
            score -= 22.0;
        }
        if next_item_size <= 20 && post_residual <= 3 * next_item_size {
            let tightness = 1.0 - after_next as f64 / (2.0 * next_item_size as f64).max(1.0);
            score -= 10.0 * tightness * (0.5 + remaining_frac);
        }
        if after_next > 0 && mean_residual > 1.0 && (after_next as f64) <= mean_residual * 1.5 {
            score -= 5.0 * (1.0 - after_next as f64 / (mean_residual * 1.5)) * remaining_frac;
        }
        if after_next > 0 && after_next % next_item_size == 0 {
            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // NEW: two-step closure — after the next item lands, can the fleet
        // mean residual close what's left? This tightens lookahead toward
        // actual bin closure instead of just fitting.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
                score -= 9.0 * (1.0 - closable / 5.0) * (0.5 + remaining_frac);
            }
        }
        // NEW: chain-closure — leftover after next item matches the fleet
        // mean, so a following placement can also close a bin.
        if open_bins_count >= 2 && mean_residual >= 1.0 && after_next >= 1 {
            let closeness = ((after_next as f64) - mean_residual).abs();
            if closeness <= 5.0 {
                score -= 7.0 * (1.0 - closeness / 6.0) * (0.4 + remaining_frac);
            }
        }
    } else if next_item_size > 0 {
        let orphan = (next_item_size - post_residual) as f64;
        score += orphan * 2.2 * (0.6 + 0.8 * remaining_frac)
            + if orphan > 0.25 * cap { 12.0 } else { 0.0 };
        if fitting_bins_count >= 2 {
            score += 14.0;
        }
        let gap_frac = orphan / next_item_size as f64;
        if gap_frac < 0.2 {
            score += 10.0 * (1.0 - gap_frac);
        }
        score += 14.0 * gap_frac * gap_frac * (0.4 + remaining_frac);
    }

    // Harmonic pairing.
    if post_residual == item_size && item_size <= bin_capacity / 2 {
        score -= 30.0;
    }

    if bin_residual != bin_capacity && bin_residual == 2 * item_size && 2 * item_size <= bin_capacity {
        score -= 14.0 * (0.5 + remaining_frac);
    }

    // Last-chance bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 280.0;
    }

    // Waste-ratio shaping.
    if waste_ratio < 0.08 {
        score -= 25.0;
    } else if waste_ratio > 0.45 {
        score += 18.0 * waste_ratio;
    }

    // Consolidation toward mean residual.
    if open_bins_count > 0 {
        score += (post_residual as f64 - mean_residual) * 0.45;
        score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);
        let spread = (post_residual as f64 - mean_residual).abs();
        let crowding = (open_bins_count.min(12) as f64) / 12.0;
        score += spread * 0.09 * crowding * (0.4 + remaining_frac);
    }

    // Open-bin pressure.
    if open_bins_count > 0 {
        score += 12.0 * (open_bins_count as f64).ln().max(1.0);
    } else {
        score -= 10.0;
    }

    // Crumbs.
    if post_residual >= 1 && post_residual <= 10 && bin_residual != bin_capacity {
        score -= 9.0;
    }

    // Near-closure gravity.
    if bin_residual != bin_capacity && post_residual >= 1 && post_residual <= 15 {
        let closeness = 1.0 - (post_residual as f64 - 1.0) / 14.0;
        score -= 5.0 * closeness * closeness;
    }

    // Dead-space accounting with fleet-absorbability exemption.
    if bin_residual != bin_capacity && post_residual > 0 {
        let dead_hi = 25.0f64.max(0.25 * cap);
        if (post_residual as f64) > 1.0 && (post_residual as f64) < dead_hi {
            let depth = (post_residual as f64 - 1.0) / (dead_hi - 1.0);
            let small_sink = (item_size as f64 / post_residual.max(1) as f64).min(1.0);
            let fleet_absorb = open_bins_count >= 2 && mean_residual >= post_residual as f64;
            let w = if fleet_absorb { 0.55 } else { 1.0 };
            score += 10.0 * w * depth * (0.5 + remaining_frac) * (0.6 + 0.6 * small_sink);
        }
    }

    // NEW: aggressive dead-space elimination — residuals below the fleet
    // mean's useful payload are nearly unrecoverable; penalize quadratically
    // mid-stream, but reward residuals that host the next item with tiny slack.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 3 && mean_residual >= 1.0 {
        let pr = post_residual as f64;
        if pr < mean_residual {
            let depth = 1.0 - pr / mean_residual;
            score += 14.0 * depth * depth * (0.3 + remaining_frac);
        }
        if next_item_size > 0 && pr >= next_item_size as f64 {
            let slack = pr - next_item_size as f64;
            if slack <= 4.0 {
                score -= 9.0 * (1.0 - slack / 5.0) * (0.5 + remaining_frac);
            }
        }
    }

    // NEW: exact-complement sweep — post residual nearly a whole multiple of
    // the next item means the bin closes with a short run of next-size items.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0 && open_bins_count >= 2 {
        let pr = post_residual as f64;
        let next = next_item_size as f64;
        if pr > next {
            let k = (pr / next).floor();
            let rem = pr - k * next;
            if rem <= 2.0 {
                score -= 10.0 * (1.0 - rem / 3.0) * (0.4 + remaining_frac) * (k.min(3.0) / 3.0);
            }
        }
    }

    // NEW: reward residuals that complement the fleet mean into a full bin.
    if bin_residual != bin_capacity && post_residual > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
        let sum = post_residual as f64 + mean_residual;
        if (sum - cap).abs() <= 3.0 {
            score -= 8.0 * (1.0 - (sum - cap).abs() / 4.0);
        }
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let big_item = item_size as f64 >= 0.6 * cap;
        let next_big = next_item_size as f64 >= 0.7 * cap;
        let next_unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size;
        let stranded = open_bins_count > 0 && bin_residual as f64 > 0.9 * cap && fitting_bins_count > 2;
        if open_bins_count == 0 || big_item || fit_ratio < 0.5 || (next_big && next_unusable) || stranded {
            score -= 25.0 + 15.0 * (1.0 - fit_ratio);
        } else {
            let crowded = open_bins_count as f64 > 4.0 + 6.0 * progress;
            score += 300.0 + 300.0 * (1.0 - progress) - if crowded { 40.0 } else { 0.0 };
            if open_bins_count > 2 && mean_residual < 0.12 * cap {
                score -= 60.0;
            }
            if fit_ratio < 0.75 && mean_residual < item_size as f64 {
                score -= 45.0;
            }
            if next_item_size > 0 && post_residual < next_item_size && mean_residual < next_item_size as f64 {
                score += 55.0;
            }
            if next_item_size > 0 && item_size as f64 > 0.5 * cap && mean_residual < next_item_size as f64 + 4.0 {
                score -= 35.0;
            }
            if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.max(1) {
                let stranded_depth = next_item_size.saturating_sub(post_residual) as f64;
                if stranded_depth > 0.35 * cap {
                    score -= 40.0;
                }
            }
            if fit_ratio < 0.85 && mean_residual < 0.18 * cap && remaining_frac > 0.5 {
                score -= 30.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if next_item_size > 0 && mean_residual < next_item_size as f64 && fit_ratio < 0.9 && remaining_frac > 0.35 {
                score -= 18.0 * (1.0 - mean_residual / next_item_size.max(1) as f64);
            }
            if open_bins_count > 5 && fit_ratio < 0.7 && mean_residual > item_size as f64 && remaining_frac > 0.25 {
                score -= 22.0 * (1.0 - fit_ratio) * remaining_frac;
            }
            if open_bins_count > 3 && mean_residual >= item_size as f64 * 1.1 && fit_ratio < 0.95 {
                score += 35.0 * (mean_residual / item_size.max(1) as f64).min(3.0);
            }
            if open_bins_count > 2 && mean_residual >= item_size as f64 + next_item_size as f64 * 0.5 && fit_ratio < 0.85 {
                score += 20.0 * remaining_frac;
            }
            if open_bins_count > 3
                && next_item_size > 0
                && mean_residual >= (item_size + next_item_size) as f64
                && fit_ratio < 0.9
            {
                score += 90.0;
            }
            // NEW: fresh-bin promise check — a new bin whose post residual is
            // below the fleet mean's reach is a wasted capacity unit.
            if open_bins_count > 2
                && mean_residual >= 1.0
                && post_residual > 0
                && (post_residual as f64) < mean_residual
                && remaining_frac > 0.25
            {
                let depth = 1.0 - post_residual as f64 / mean_residual;
                score += 26.0 * depth * depth * remaining_frac;
            }
            // NEW: reward a fresh bin that closes the item exactly when other
            // open bins would strand dead space.
            if post_residual == 0 && open_bins_count > 0 && fit_ratio < 0.95 {
                score -= 34.0 * (1.0 - fit_ratio) * (0.5 + remaining_frac);
            }
            // NEW: a fresh bin whose post residual pairs with the fleet mean
            // into a near-full bin promises future closure.
            if open_bins_count >= 2
                && mean_residual >= 1.0
                && post_residual > 0
                && ((post_residual as f64 + mean_residual) - cap).abs() <= 6.0
            {
                score -= 20.0 * (1.0 - ((post_residual as f64 + mean_residual) - cap).abs() / 7.0);
            }
            // NEW: refuse a fresh bin whose own post residual would be a
            // dead-end (below next item and below fleet-mean pairing reach).
            if open_bins_count > 2
                && next_item_size > 0
                && post_residual > 0
                && (post_residual as f64) < next_item_size as f64
                && (post_residual as f64 + mean_residual) < next_item_size as f64
                && remaining_frac > 0.2
            {
                score += 45.0 * remaining_frac;
            }
        }
    }

    // Late-stream tightening.
    if remaining_frac < 0.15 && bin_residual != bin_capacity {
        score -= (0.15 - remaining_frac) * 120.0 * (1.0 - waste_ratio);
    }

    // Mid-stream consolidation nudge.
    if fitting_bins_count >= 4 && next_item_size > 0 && mean_residual < 0.2 * cap {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 6.0;
        }
    }

    // Split-fit insurance.
    if next_item_size > 0 && next_item_size as f64 > mean_residual.max(1.0) * 1.6
        && post_residual < next_item_size && fitting_bins_count >= 2 {
        score += 8.0;
    }

    // Residual-value conservation.
    if open_bins_count >= 5 && remaining_frac > 0.4 && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr >= next_item_size as f64 && pr < 0.5 * cap {
            score -= 4.0 * (pr / (0.5 * cap));
        }
    }

    // Bin-pair complementarity.
    if open_bins_count >= 3 && bin_residual != bin_capacity && next_item_size > 0 {
        let pr = post_residual as f64;
        if pr > next_item_size as f64 && pr < 0.6 * cap {
            let pairable = (pr + mean_residual - cap).abs();
            if pairable < 0.1 * cap {
                score -= 7.0 * (1.0 - pairable / (0.1 * cap));
            }
        }
    }

    // Dead-zone floor lift.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < mean_residual && mean_residual > 1.0 {
            score += 4.0 * (1.0 - slack / mean_residual) * remaining_frac;
        }
    }

    // Fleet-incapable residue penalty.
    if bin_residual != bin_capacity && post_residual > 0 && next_item_size > 0
        && post_residual < next_item_size && mean_residual < next_item_size as f64 {
        score += 8.0 * remaining_frac;
    }

    // Dead-zone width guard.
    if bin_residual != bin_capacity && next_item_size > 0 && post_residual > next_item_size {
        let band = post_residual - next_item_size;
        if band >= 1 && band <= 8 && next_item_size >= 8 {
            score += 5.0 * (band as f64 / 8.0) * remaining_frac;
        }
    }

    // Avoid stranding medium residue when a near-exact alternative exists.
    if next_item_size > 0 && post_residual > next_item_size && post_residual < 2 * next_item_size {
        let frac = (post_residual - next_item_size) as f64 / next_item_size as f64;
        if frac > 0.6 {
            score += 9.0 * frac;
        }
    }

    // Divisible residue chains.
    if bin_residual != bin_capacity && next_item_size > 0 && next_item_size <= 15 && post_residual > next_item_size {
        if post_residual % next_item_size == 0 {
            score -= 5.0 * (0.3 + remaining_frac);
        }
    }

    // NEW: early-stream consolidation — keep early residuals above the fleet
    // mean so future medium items still have hosts.
    if bin_residual != bin_capacity
        && post_residual > 0
        && open_bins_count >= 2
        && open_bins_count <= 6
        && remaining_frac > 0.6
        && mean_residual >= 1.0
    {
        let pr = post_residual as f64;
        if pr < mean_residual * 0.6 {
            score += 5.0 * (1.0 - pr / (mean_residual * 0.6).max(1.0)) * remaining_frac;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits, but treat unusable small gaps as dead space.
    let pr = post_residual as f64;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 50.0;
    } else if post_residual < 10 {
        // Unusable dead space (smaller than any item): heavy penalty.
        score += 40.0 + (10.0 - pr) * 3.0;
    } else {
        // Usable residual: mild preference for smaller leftovers.
        score += pr * 0.15;
    }

    // New-bin candidate: opening a bin costs, unless current fits are poor.
    if bin_residual == bin_capacity {
        let poor_fits = (fitting_bins_count as f64).max(1.0);
        // Penalize opening a new bin; relax penalty when few alternatives.
        score += 25.0 / poor_fits.sqrt() + open_bins_count as f64 * 0.5;
        // If item is large and next item may need space, opening is less bad.
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Open bins pressure: discourage spreading across many bins slightly.
    score += open_bins_count as f64 * 0.05;

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 30.0;
        } else {
            score -= gap as f64 * 0.05;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this bin's leftover: slight penalty for wasted space.
        score += pr * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Early stream: be more conservative with new bins; late stream: tighter packing.
    let progress = step_index as f64 / total_items as f64;
    score += (1.0 - progress) * pr * 0.05;

    // Mean residual coupling: when mean residual is high, prefer bins with
    // residual close to mean (avoid outliers).
    score += (pr - mean_residual).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
