            let k = after_next / next_item_size;
            score -= 4.0 * (k.min(4) as f64 - 1.0) * (0.4 + remaining_frac);
        }
        // Two-step closure toward the fleet mean: the leftover after the next
        // placement should be closable by the mean residual — a near-full
        // bin two steps out is the strongest compaction signal.
        if after_next > 0 && open_bins_count >= 2 && mean_residual >= 1.0 {
            let closable = (after_next as f64 + mean_residual - cap).abs();
            if closable <= 4.0 {
